COLLDATA("tadabburur","ur",[[453,"§ص\ndeeds\nیہ دعا پڑھئے: “لَا اِلٰهَ اِلَّا اللّٰهُ وَحْدَهٗ لَا شَرِيْكَ لَهٗ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ”اللہ کے سوا کوئی معبود برحق نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں اسی کے لئے بادشاہت ہے اسی کے لئے سب تعریف ہے اور وہی ہر چیز پر کامل قدرت رکھتا ہے.\nیہ دعا پڑھئے: “اَللّٰهُمَّ اهْزِمِ الْكَفَرَةَ الَّذِيْنَ يَصُدُّوْنَ عَنْ سَبِيْلِكَ، وَيُعَادُوْنَ أَهْلَ دِيْنِكَ” اے اللہ! تو ان کافروں کو شکست دے جوتیری راہ سے لوگوں کو روکتے ہیں اور تیرے دین کو ماننے والوں سے دشمنی کرتے ہیں.\nآج تفسیر كى كوئى ایسى كتاب پڑھئے جس میں آپ كے اس درس كى شرح ہو جسے آپ نے قرآن سے سیکھا ہے.\nguid\nگزشتہ ان امتوں سےعبرت لیجئے جنہیں الله نے ہلاك كردیا ہے.\nحق كى طرف بلانے والوں كا مزاق اڑانا اور انہیں گالى گلوچ دینا، قیامت تك باقى رہنے والا دستورِ الٰہی ہے، لہذا یہ آپ کے لئے رکاوٹ نہ بنے.\nالله كى نعمتوں پر لوگوں سے حسد مت كیجئے، كیونكہ اس سے قضاء وقدر پر اعتراض لازم آتاہے.\nrefl\nوَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ ١ بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ ٢\nیعنى اس قرآن میں ان كیلئے نصیحت اور عبرت ہےجو نصیحت حاصل كرتے اور عبرت پكڑتے ہیں۔ البتہ كافروں كو اس سے كوئى فائده نہیں ہوگا كیونكہ وه گھمنڈ و جاہلی حمیت كے شكار ہیں، مخالفت ، عناد اور دورى اپنانے پر تلے ہیں۔ (ابن كثیر: ۴؍۲۸)\nاس آیت میں قرآن سے استفادے كى راه میں حائل جن رکاوٹوں کا تذکرہ کیاگیا ہے انہیں ذکر کیجئے.\nبَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةٖ وَشِقَاقٖ ٢\nبعض اہل علم كا قول ہے كہ (شِقَاقٍ) مشقہ سے ماخوذہے، كیونكہ مخالف ومعاند اپنے مخالف و معاند تك مشقت پہنچانے کی کوشش کرتا ہے، بعض كہتےہیں كہ یہ ‘‘شق العصا’’سے مشتق ہے، یعنى اختلاف و انتشار۔ (الشنقیطى: ۶؍۳۳۰)\nالله تعالىٰ نے كافروں كى یہ صفت كیوں بیان كى ہے كہ وه مخالفت میں پڑےہیں؟\nوَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرٞ كَذَّابٌ ٤\nلفظ (هذا)سے مشركین كا اشاره رسول الله صلی اللہ علیہ وسلم كى طرف تھا، انہوں نے آپ صلی اللہ علیہ وسلم کی تحقیر کے لئے(هذا) اسم اشاره استعمال كیا تھا ۔ (ابن عاشور: ۲۳؍۲۰۹)\nمشركین نے نبى كریم صلی اللہ علیہ وسلم كیلئے اسم اشاره كیوں استعمال كیا تھا؟\nوَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءٞ يُرَادُ ٦\n(لَشيء يُراد) یعنى اس كے پیچھے كچھ مقصد ہے، مطلب اس سلسلے میں اس كى نیت خراب ہے، یہ شبہ صرف كم عقلوں اور نادانوں میں مقبول ہوسکتا ہے، كیونكہ جو شخص حق یا ناحق بات كى طرف بلاتا ہےتو اسكى بات اسكى نیت پر جرح كركے رد نہیں كى جاتى کیونکہ اس کی نیت و عمل تو اس کے پاس ہے بلكہ دلیل وحجت سے ان کی باتوں كى تردید كى جاتى ہے۔(السعدى: ۷۱۰)\nاس آیت كى روشنى میں واضح كیجئے كہ آپ اس شخص كى تردید كیسے كرینگے جو علماء ودعاة كى نیتوں میں كیڑے نكالتا ہو؟\nأَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكّٖ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ ٨\nمحض بہت ڈھیل دینے کی وجہ سے یہ دھوكے میں پڑگئے ہیں اگر شرك پر میرا عذاب چكھ لیتےتو ان كا شك دور ہوجاتا۔(القرطبى: ۱۸؍۱۳۵- ۱۳۶)\nكافروں كے شرک پر اصرار اور ان كے دھوكہ كا سبب كیا ہے؟\nجُندٞ مَّا هُنَالِكَ مَهۡزُومٞ مِّنَ ٱلۡأَحۡزَابِ ١١\nیہ جنگ میں ان كے شكست كى وعید ہے اور بالفعل بدر وغیره میں ان كى ہار ہوئى بھى۔ (ابن جزى: ۲؍۲۴۸)\nالله تعالىٰ نے اپنے نبى سے مشركین كى شكست كا وعده اسى وقت كردیا تھا جبكہ دعوت دین كا ابتدائى دور تھا اور مكہ میں مسلمان كمزور تھے ، بتائیے كہ یہ وعده پورا كب ہوا؟\nكَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ ١٢\nفرعون كى عظیم بادشاہت اور اسكى قوت وشوكت كیوجہ سے اسكى صفت (ذو الأوتاد ) میخوں والے سے بیان كى گئى ہے، پھر بھى یہ عظمت اسكے اور الله كے عذاب كےبیچ حائل نہیں ہوسكى۔(ابن عاشور: ۲۳؍۲۲۰)\nفرعون كى ایک صفت (ذو الأوتاد ) بیان کی گئی ہے، بتائیے اس كا فائده كیا ہے؟\nwords\nالمِلَّةِ الآخِرَةِهمارے آباء كا دين ؛ دين نصاري.\nاختلاقجھوٹ اور من گھڑت.\nفَليَرتَقُوا فِي الأَسبَابِپس چاهيے وه آسمان تك رسائي كے اسباب اختيار كريں.\nوَأَصحَابُ الأَيكَةِاصحاب اشجار؛ و باغوں والے۔ قوم شيعب عليه السلام.\nفَوَاقٍرجوع.\nقِطَّنَاعذاب ميں همارا حصه."],[454,"§ص\ndeeds\nاپنے لئے صبح و شام کے اذکار اور تسبیح کا ایک وظیفہ بنائیے.\nیہ دعا پڑھئے: “اَللّٰهُمَّ اِنِّيْ أَعُوْذُبِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمُ، أَوْ أَجْهَلَ أَوْ يُجَهَلَ عَلَىَّ” اے اللہ! میں تیری پناہ میں آتا ہوں اس بات سے کہ میں گمراہ ہوجاؤں یا مجھے گمراہ کردیا جائے یا میں پھسل جاؤں یا مجھے پھسلادیاجائے، یا میں ظلم کروں یا مجھ پر ظلم کیا جائے، یا میں کسی سے جہالت سے پیش آؤں یا میرے ساتھ جہالت سے پیش آیاجائے.\nسو بار الله سے استغفار كیجئے اور اپنے استغفار كى قبولیت كا الله سے سوال كیجئے.\nguid\nانبیاء وصالحین كے قصے ہمیشہ یاد ركھئے اور انہیں بیان بھى كیجئے.\nجو آپ كو ایذاء دے اسكى ایذا رسانى پر صبر كیجئے.\nخواہشات نفس كى پیروى سے بچئے، اسلئے كہ یہ خود گمراه ہونے اور دوسروں كو گمراه كرنے كا سبب ہے اور فیصلہ كرتے وقت عدل و انصاف اور حق كو لازم پكڑئیے.\nrefl\nٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ ١٧\nداؤد علیہ السلام اور انكے بعد دیگر انبیاء كا تذکرہ رسول الله صلی اللہ علیہ وسلم كى تسلى كیلئے ہے، انكے غم كا ازالہ اور ان كى مدد كا وعده ہے اور اس صبر پر تعاون ہے جس كا انہیں حكم دیا گیا تھا، كیونكہ الله نے داؤد علیہ السلام پر اپنے ان احسانات كا تذكره كیا: پہاڑوں وپرندوں كو انكے لئے مسخر كرنا، انكى بادشاہت كى صلابت وسختى، انہیں حكمت سے نوازنا اور درست فیصلے كى صلاحیت بخشنا پھر اس بات پر خاتمہ كرنا كہ انكے لئے آخرت میں بڑا مرتبہ اور اچھا ٹھكانہ ہے۔ گویا كہ الله یہ فرما رہا ہے كہ اے محمد! جس طرح ہم نے ان نعمتوں سے داؤدعلیہ السلام كو نوازا ہے آپ کو بھى نوازیں گے، لہذا آپ صبر كریں اور ان كى باتوں سے دلبرداشتہ نہ ہوں۔ (ابن جزى: ۲؍۲۴۹)\nاللہ تعالیٰ کامحمد صلی اللہ علیہ وسلم كو صبر اور داؤد علیہ السلام کو یاد کرنے کا حکم دینے میں کیا مناسبت ہے؟\nٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ ١٧\nداؤد علیہ السلام كے قصے کے فوائداور حکمتیں:الله اپنى اطاعت كے كاموں میں قلب وبدن كى قوت پسند فرماتاہے اور اسكى تعریف بیان كرتاہے، اسلئے كہ اس سے جس قدر بکثرت و حسن و خوبی کے ساتھ نیکی کے کام انجام پاتے ہیں وه کمزوری اور لاغری میں قطعی انجام نہیں پاتے ہیں۔ پس بندوں کو چاہئے كہ طاقت كے اسباب اپنائے اور ایسی سستی اور کاہلی پر اعتماد نہ کرے جو قوت و نشاط کو برباد کرکے نفس کو کمزور کردے۔ (السعدى: ۷۱۳)\nالله تعالىٰ اپنى طاعت میں قوت وطاقت پسند فرماتا ہے، یہ چیز آپ اس وصف كى روشنى میں بیان كیجئے جو الله نے داؤد علیہ السلام كیلئے (ذَا الأيد) (یعنى طاقت والا) كہہ كر بیان كیا ہے.\nوَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ ٢٠\nداؤد علیہ السلام كے قصے كاایك فائده یہ بھى ہے كہ بندے پر اللہ تعالیٰ کی سب سے عظیم نعمتوں میں سے ایک نعمت یہ كہ الله اسے علم ِنافع سے نوازے اور لوگوں كے بیچ فیصلے کرنے کا ملکہ بھی حاصل ہوجائے جیسا كہ الله نے اپنے بندے داؤد علیہ السلام كو ان صفات سے نوازا تھا۔(السعدى: ۷۱۳)\nالله تعالىٰ نے داؤد علیہ السلام كو حكمت سے نواز كر ان پر جواحسان كیا تھا اس سے آپ كیا فائده اخذ كرسكتےہیں؟\nإِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعٞ وَتِسۡعُونَ نَعۡجَةٗ وَلِيَ نَعۡجَةٞ وَٰحِدَةٞ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ ٢٣ قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ٢٤\nبنو اسرائیل کی کتابوں میں یہ قصہ نازیبا انداز میں وارد ہے ، جسے قصہ گووؤں نے اس امت کے ابتدائی دور میں بیان کیا تو على رضی اللہ عنہ نے كہا كہ داؤد علیہ السلام كے بارےمیں ان قصہ خوانوں كى بات اگر كوئى بیان كرےگا تو میں اس پر دو حد نافذ كرتےہوئے كوڑے لگاؤں گا كیونكہ اس نے ایسے نفوس قدسیہ کے بے حرمتی کی جن کے مقام و مرتبہ کو اللہ نے بلند کیا ہے۔ (ابن عطیہ : ۴؍۴۹۹)\nعلى رضی اللہ عنہ سے اس قصے كے سلسلے میں جو منقول ہے اس میں مقام نبوت کا تحفظ ہے اس کی وضاحت كیجئے.\nوَإِنَّ كَثِيرٗا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلٞ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ٢٤\nسوائے ان كے جو ایمان لائے اور نیك كام كئےہیں ، كیونكہ یہ كسى پر ظلم نہیں كرتے اور ایسے لوگ بہت كم ہیں، یعنى نیك اور پرہیزگار لوگ ۔(القرطبى: ۱۸؍۱۷۲)\nیہ آیت كریمہ پارٹنر(شریك) اختیار كرتےوقت ایمان اور نیكى كى رعایت پر ابھارتى ہےاس کی وضاحت کیجئے.\nوَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعٗاۤ وَأَنَابَ۩ ٢٤ فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ\nتوبہ و استغفار اور عبادت – بطور خاص نماز- گناہوں کو مٹانے والی ہے، كیونكہ اللہ نے داؤد علیہ السلام كے گناه كى بخشش کو ان کے استغفار اور سجدے کا نتیجہ قرار دیا ہے۔(السعدى: ۷۱۳)\nگناه کو مٹانے میں نماز كى اہمیت کو آیت كى روشنى میں واضح كیجئے.\nيَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةٗ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ ٢٦\nاكثر كمالات كا حال یہ ہے کہ وه نفس پر گراں گزرتى ہیں كیونكہ انكا تعلق تہذیب نفس اور حیوانى پستى سے نفس کو بالا وبرتر کرنے سے ہوتاہے، چنانچہ نفس كى پیروى میں انہماک عموما رزالت كى كھائى میں دھكیل دیتا ہے۔(ابن عاشور: ۲۳؍۲۴۴)\nخواہشات نفس كى پیروى بلند درجات تك رسائى كى راه میں ركاوٹ ہے، اسے آیت كى روشنى میں بیان كیجئے.\nwords\nذَا الأَيدِجنگ ميں اطاعت گزاري پر صاحب قوت.\nأَوَّابٌبهت زياده الله كي رضامندي كي طرف رجوع كرنے والا.\nوَلاَ تُشطِطاور آپ ظلم نه كريں/ فيصله كرنے ميں.\nأَكفِلنِيهَاميرے حواله كردو۔ ميرے حق ميں تنازل اختيار كرو.\nالخُلَطَاءِشركاء.\nلَزُلفَىيقيني قربت / مقام و مرتبه.\nمَآبٍمرجع / ٹھكانا."],[455,"§ص\ndeeds\nعم پارے كى كسى سورت كى تلاوت كیجئے، اس كا معنى معلوم كیجئے اور اسكے فوائد اور اسكے علم وعمل پر غور وفكر كیجئے.\nآپ كسى ایسى چیز کا پتہ کیجئے جو آپ كو الله كى اطاعت سے روك رہى ہے اور اسے الله كى راه میں صدقہ كردیجئے، شاید الله آپ كو اس سے بہتر بدلہ دےدے.\nابنیاء كرام كى اقتداء کرتے ہوئےالله تعالىٰ سے دنیا وآخرت كى بھلائى طلب كیجئے.\nguid\nجان لیجئے كہ صحیح وسالم عقل والے ہی نصیحتوں سے عبرت پكڑتےہیں اور بھرپور مستفید ہوتے ہیں.\nاس بات سے بچئے كہ دنیا كى كوئى چیز آپ كو الله كى اطاعت سے غافل كردے.\nجب آپ سے كوئى خطا سرزد ہوجائے یا كوئى غم وپریشانى لاحق ہو تو زیاده سے زیاده توبہ کیجئے اور اللہ کی طرف رجوع کیجئے.\nrefl\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٩\nبظاہر آیت كریمہ سے معلوم ہوتاہے كہ قرآن میں تدبر كرنا نزول قرآن كا ایك سبب ہے، چنانچہ جلدى جلدى پڑھنے كے مقابلے میں ترتیل یعنى ٹھہر ٹھہر كر پڑھنا زیاده بہتر ہے، كیونكہ تدبر ترتیل كے بغیر ممكن نہیں ہے۔(ابن عطیہ : ۴؍۵۰۳)\nتدبر اور ترتیل كے درمیان كیا تعلق ہے؟ واضح كیجئے.\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٩\nقرآن كى ہر آیت میں بركت ہے، كیونكہ یہ یا تو كسى بھلائى كى طرف رہنمائى كرتى ہے یا کسی شر وفساد سے روكتى ہے، اور یہى دنیا اور آخرت کی بھلائی کا سبب ہے، بھلا اس سے بڑى بركت اور كیا ہوسكتى ہے! (ابن عاشور : ۲۲؍۲۵۱)\nالله كى پورى كتاب بابركت ہے ، اسے آیت كریمہ كى روشنى میں بیان كیجئے.\nكِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٩\n(أولو الألباب) سے مراد عقل والے ہیں اور اس میں اس نکتہ کی طرف اشاره ہے كہ جو لوگ قرآن سے نصیحت حاصل نہیں كرتے وه عقلمند نہیں ہیں، اورعبرت حاصل كرنا مسلمانوں كا شیوه ہے، جو كہ باتوں كو بغور سنتےہیں پھر جو بہترین بات ہو اس کی اتباع کرتے ہیں۔ چنانچہ یہی لوگ قرآنی آیات میں تدبرکرتے ہیں اور ایسے معانی مستنبط کرتے ہیں جو انہیں معلوم نہیں تھے ۔ جبكہ كافروں كا حال یہ ہے کہ وه غور كرنے سے بھاگتے ہیں اسى لئے عبرت پذیرى ان میں مفقود ہے۔ (ابن عاشور: ۲۳؍۲۵۳)\nآیت كریمہ كى روشنى میں عقلمندوں كى نشانى بیان كیجئے.\nفَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ ٣٢\nگھوڑے کو خیر كہاگیا ہے كیونكہ خیر یعنى اجر اور مال غنیمت اس كى پیشانیوں میں باندھ دیاگیا ہے۔(البغوى: ۳؍۷۰۳)\nگھوڑے کو خیر كیوں كہاگیا ہے؟\nقَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ٣٥\nسلیمان علیہ السلام نےاستغفار کو بادشاہت كى طلب پر مقدم کیاہے، اسلئے كہ انكے نزدیك دینى امور دنیا سے كہیں زیاده اہم تھے، لہٰذا اولىٰ واہم كو پہلے ركھا۔(ابن جزى: ۲؍۲۵۵)\nسلیمان علیہ السلام نے بادشاہت كى طلب پر استغفار كومقدم كیوں كیا؟\nقَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ٣٥ فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ ٣٦\nحسن بصری سے مروى ہے كہ الله كے نبى سلیمان علیہ السلام پر جب گھوڑے پیش كئے گئے تو ان كے معاینے نے انہیں نماز عصر سے مشغول كردیا، یہاں تك كہ سورج غروب ہوگیا۔ چنانچہ وه الله كیلئے خفا ہوئے اور انہیں ذبح كرنے كا حكم دے دیا، جب گھوڑے ذبح كر دئیے گئے تو الله نے بدلے میں ان سے تیزرو چیز عطا كردى یعنى ان كے لئے ہواؤں كو مسخر كردیا وه آپ كے حكم سےآپ جہاں چاہتے بہ آسانی پہنچا دیا كرتى تھیں۔ (الطبرى: ۲۱؍۲۰۱- ۲۰۲)\nآیت كى روشنى میں بیان كیجئے كہ اگر كوئى شخص الله كیلئے کچھ چھوڑتا ہے تو الله تعالىٰ بدلے میں اس سے بہترچیز عطا كردیتاہے.\nوَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ ٤١\nایوب علیہ السلام كے احوال میں سے بطور خاص اپنے رب كو پكارنے والى حالت ذكر كى گئى ہے، كیونكہ یہ ان کا اپنےرب پر توكل کا اظہار اور اللہ تعالیٰ کاان کی دعاقبول فرماکر ان کی تکلیف دور کرنے کا مقام تھا۔(ابن عاشور: ۲۳؍۲۶۸)\nایوب علیہ السلام كےدیگر احوال كو چھوڑ كر خاص طور سے انكے اپنے رب كو پكارنے والى حالت كا تذكره كیوں كیا گیا ہے؟\nwords\nالصَّافِنَاتُتين پاؤں پر كھڑے گھوڑے / وجه ان كي عمدگي.\nالجِيَادُاصلي اور تيز ترين گھوڑے.\nفَطَفِقَاس نے شروع كيا.\nمَسحًا بِالسُّوقِ وَالأَعنَاقِان كي گردنوں اور پنڈليوں كو كاٹا/ تقرب إلي الله كے ليے.\nرُخَاءًنرم.\nبِنُصبٍمشقت / تھكاوٹ."],[456,"§ص\ndeeds\nاپنا كوئى ایسا مسئلہ یاد كیجئے جس پر آپ نے صبر كیا ہو اور دعا كیجئے كہ الله اسے اپنى عبادت كا درجہ دےدےاور اسے آپ كے میزان حسنات كا حصہ بنادے.\nاپنى كوئى قسم جو كھا ركھى ہو یاد كیجئے اور حكم الٰہى كى تعظیم میں اس قسم کو پورا کرنے کی کوشش کیجئے.\nالله سے دعا كیجئے كہ وه اسى دنیا كو آپ كى عنایتوں كا سب سے بڑا محور نہ بنائے.\nguid\nكبھى كبھى الله تعالىٰ اپنےمحبوب بندوں کو ان کے مقام و مرتبہ بلند کرنے کے لئے آزمائش میں مبتلا كردیتا ہے.\nوه تعلق جس كى بنیاد الله كى ناراضگى پر ہو وه آخرت میں کھلی دشمنى میں بدل جائےگى.\nآپ كسى کی معصیت كا سبب مت بنئے.\nrefl\nوَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ\nاسكى وجہ یہ ہے کہ ایوب علیہ السلام اپنى بیوى پر كسى وجہ سے ناراض ہوگئے تھے اور بیمارى كى حالت میں قسم كھالى كہ اگر الله نے انہیں شفادى تو وه اس (بیوی) کو سو كوڑے ماریں گے چنانچہ جب الله نے شفا دے دى تو ظاہر ہے پورى پورى خدمت كرنے والى انتہائى مہربانی و شفقت و احسان كا برتاؤ كرنےوالى بیوی كا بدلہ مار نہیں تھا۔ اس لئے اللہ تعالیٰ نے انہیں حکم دیا كہ ایك گٹھا کھجور کا خوشہ لیں جس میں سوتنکے ہوں اور اسى سے ایك بار بیوى كو ماریں، تاكہ قسم پورى ہوجائےاور وہ قسم ٹوٹنے سے بچ جائیں۔ اور نذر بھی پوری ہوجائے یہ کشادگی اللہ سے ڈرنے والوں اور اس کی طرف رجوع کرنے والوں کے لئے ہے۔ (ابن كثیر: ۴؍۴۱)\nجو شخص صحیح معنوں میں الله سے ڈرتا ہے الله تعالىٰ اس كے لئے كوئى راستہ نكال دیتاہے ، آیت كى روشنى میں اسكى وضاحت كیجئے.\nوَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ ٤٥\n(الأيدي )الید كى جمع ہے، یہ نیك كاموں میں انكى قوت وطاقت سے عبارت ہے، اسكى تعبیر ہاتھ سے كى گئى ہے كیونكہ اكثر كام ہاتھوں سے انجام پاتےہیں اور (الأبصار) یعنى آنكھیں تو یہ ان کی قوت فہم اور كثرت علم سے عبارت ہے، جیسے اہل عرب “ابصر الرجل”اس شخص كیلئے كہتےہیں جس كیلئے معاملات واضح ہوں ، اور وہ ہر گوشے سے واقف ہو۔(ابن جزى: ۲؍۲۵۷)\nالله تعالىٰ نے اپنے انبیاء كیلئے (أولى الأيدي والأبصار) كى صفت مدح استعمال كى ہے، ان صفات كى وضاحت كیجئے.\nهَٰذَا ذِكۡرٞۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابٖ ٤٩\nیہ انبیائے کرام کا تذکرہ ہے، یعنى دنیا میں ان کا ذکرخیر ہے اوریہ تذکرہ ایسا شرف ہے جسے لوگ دنیا میں ہمیشہ یاد رکھیں گے اور متقیوں كے لئے بہترین ٹھكانہ ہے ۔ یعنى ان كے لئے دنیا میں اس ذكر خیر كےساتھ آخرت میں اچھى جگہ ہے۔(القرطبى: ۱۸؍۲۲۶)\nاس آیت میں دنیا وآخرت میں متقیوں کے بعض بدلے کا ذكر كیا گیا ہے، اسكى وضاحت كیجئے.\nمُّفَتَّحَةٗ لَّهُمُ ٱلۡأَبۡوَٰبُ ٥٠\nیہ مکمل امن و امان کی بھی ایک دلیل ہے، كہ وہاں ہمیشگى والى جنت میں كوئى ایسى چیز نہیں ہوگى جسكى وجہ سے اسكے دروازے بند ہوں۔ (السعدى: ۷۱۵)\nآیت میں اہل جنت كى ایك عظیم نعمت كى طرف اشاره ہے، جس سےالله ا نہیں سرفراز كرےگا، وه كیا ہے؟\n۞وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ ٥٢\nاور انكےپاس بڑى بڑى آنكھوں والى حوریں ہونگى ، انكى نگاہیں اپنے شوہروں سے تجاوز نہیں کریں گی اور ان کے شوہروں کی نگاہیں بھی انہیں پر ٹکی رہیں گی، ایسا ان سب كى بے پناه خوبصورتى اور ہرایک کی دوسرے سے بھرپور محبت کرنے اور ان میں دوسروں کی خواہش نہ ہونے کی وجہ سے ہوگا نیز وہاں نہ کوئی اپنے ساتھی کے بدیل پر راضی ہوگا اور نہ ہی اس کے عوض پر۔ (السعدى: ۷۱۵)\nحوروں كى صفت (قاصرات الطرف) (نیچى نگاه والیاں) سے بیان كرنے میں ایك ایسے اخلاق كى طرف اشاره ہے جس سے دنیا میں مسلمان عورت كو متصف ہونا چاہئیے ، اور شاید وہى صفت اس كے جنت میں داخلے كا سبب بن جائے ۔ بتائیے وه كیا ہے؟\nإِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ ٥٤\nوه اس طور پر كہ جب وه جنت كے درختوں میں سے كسى درخت كا پھل لیكر كھائیں گے تو اسكى جگہ دوسرا پھل تیار ہوجائے گا اور یوں انكے لئے ہمیشہ رہےگا كبھى ختم نہ ہوگا۔(الطبرى: ۲۱؍۲۲۳)\nآیت میں جنت اور دنیا كےپھلوں كےدرمیان كونسا فرق بیان كیا گیاہے؟\nقَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ ٦٠\nیعنى تم نے ہمیں نافرمانى كى دعوت دى پس ہمارے اور تمہارے سب كیلئےٹھہرنے کی بڑى برى جگہ ہے، وه كہیں گے یعنى پیروكار كہیں گے : اے ہمارے رب! جس نے ہمارے لئے یہ(نافرمانی کی دعوت) پیش كیا ہے اسے جہنم كا دہرا عذاب دے۔(القرطبى: ۱۸؍۲۳۳)\nنافرمان مقتداؤں كےبارےمیں پیروكاروں كا قیامت كے دن كیا موقف ہوگا ؟ اور اس سے آپ كیا استفاده كر رہےہیں؟\nwords\nضِغثًاجھاؤ كي گٹھڑي /حشيش كا دسته.\nوَلاَ تَحنَثاپني قسم نه توڑ.\nأَخلَصنَاهُم بِخَالِصَةٍهم نے ايك عظيم خصلت كے ساتھ ان كو خاص كيا.\nقَاصِرَاتُ الطَّرفِوه اپنے شوهروں كے علاوه كسي كو نه ديكھيں گي.\nأَترَابٌهم عمر.\nنَفَادٍمنقطع هونا.\nلَشَرَّ مَآبٍآخرت ميں بهت برا ٹھكانا."],[457,"§ص\ndeeds\nاس مسلمان بھائى سے معافى طلب كیجئے جس كا آپ نے كسى روز مذاق اڑایا ہے ، یا اسكى جانب سے صدقہ كیجئے، یا سچى توبہ كےساتھ اسكے لئے مغفرت طلب كیجئے.\nشیطان كى گمراہى اور اسكى پیروى سے الله سے پناه طلب كیجئے.\nالله سے دعا كیجئے كہ وه آپ کو اپنے چنیدہ بندوں میں شامل كرلے.\nguid\nجہنمیوں كا جھگڑا نفسیاتی عذاب ہے جو حسی عذاب سے بھی بڑھ کر ہے.\nجو لوگ نفسیاتى بیمارى جیسے كبروحسد وغیره میں مبتلا ہیں ان كا علاج اپنى دعاؤں سے كیجئے.\nبے جا حمیت وغیرت اور كبر وغرور سے بچئے كیونكہ یہ ایسا گناه ہے جس كے پاداش میں شیطان جہنم رسید ہوا.\nrefl\nوَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالٗا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ ٦٢\nیعنى جنہیں بدنصیب سمجھتےتھے، سوچتے تھے كہ اسلام كى اتباع اور تنگ دستی کی زندگی سے مطمئن ہونے كى وجہ سے یہ دنیا كى لذت سے محروم ہیں ۔ (ابن عاشور: ۲۳؍۲۹۲)\nجہنمیوں كا ایك نفسیاتى عذاب یہ ہوگا كہ انكے اس پیمانے كى غلطى كا پول كھولا جائے گا جس پر دنیا میں قیاس كركے لوگوں پر حكم لگاتے تھے، آیت كى روشنى میں اسے واضح كیجئے.\nقُلۡ إِنَّمَآ أَنَا۠ مُنذِرٞۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ٦٥\nاس ٹھوس دلیل سے الله كى الوہیت ثابت كى گئى ہے اور وه دلیل ہے الله كى وحدت اور ہرچیز پر اسی کا غلبہ ، اس لئے كہ غلبہ وحدانیت كو لازم ہے،کیونکہ دو طاقتور کبھی غلبہ میں برابر نہیں ہوسکتے، چنانچہ جو ہر چیز پر غالب ہے وہ یكتا وبے نظیر ہے وہى تنہا عبادت كا مستحق بھى ہےجس طرح وہی تنہا تمام چیزوں پر غالب ہے۔ (السعدى: ۷۱۶)\nالله تعالىٰ نے اپنى دونوں صفت “واحد وقہار” كو ایك ساتھ كیوں ذكر كیا؟\nقُلۡ هُوَ نَبَؤٌاْ عَظِيمٌ ٦٧\nآپ انہیں ڈراتے اور آگاه ومتنبہ كرتےہوئے بتادیجئے كہ یہ بہت بڑى خبر ہے، یعنى میں تمہیں جس بعث ونشور اور اعمال کے جزا وسزا سے آگاه كررہاہوں وه بہت بڑى خبر ہے، اس سے اعراض نہیں كیا جاسكتابلكہ اس پر شدید توجہ كى ضرورت ہے۔ (السعدى: ۷۱۶)\nجب آپ اس بات سے آگاه ہوگئے كہ قیامت كا دن اور حساب وكتاب انتہائى سنگین معاملہ اور كافى بڑى خبر ہے تو ایسے میں آپكو كیا كرنا چاہئیے؟\nإِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ ٧٤\nابلیس کے سرشت میں کبر وغرور اور نافرمانی کی جو صفت چھپی ہوئی تھی وہ ظاہر ہوگئی جو اس سے پہلے اس لئے ظاہر نہیں ہوئی تھی كہ وه جس جماعت كےساتھ رہتاتھا وه حسن صحبت كے کامل واعلیٰ معیار پرفائز تھى، لہٰذا کبھی ان کی طرف سے ایسی باتیں نہیں آئیں جو ابلیس کےدل میں بسنے والی طبعى غرور و نافرمانى کو بھڑکائے، لیكن جب الله نے اپنے فرشتوں کے علاوہ ایك نئى مخلوق پیدا فرمائى اور انہیں اسكى تعظیم كا حكم دیا تب ابلیس کے دل کے کبروغرور کا بھانڈا پھٹا پھر اس کا کفر اور نافرمانی سامنے آئى۔(ابن عاشور: ۲۳؍۳۰۱)\nابلیس كا طبعى غرور كس سبب سے ظاہر ہوا؟\nقَالَ يَٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ ٧٥ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ٧٦\nیہ الله تعالىٰ كى جانب سے ان مشركین كیلئے عتاب ہے جو اس گھمنڈ میں محمد صلی اللہ علیہ وسلم كا انكار كرتےہیں كہ اپنے ہى میں سے ایك آدمى كے تابعدار كیسے بن جائیں اور كہتےہیں كہ ﴿أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَا﴾ (ص: ۸) (كیا ہم سب میں سے اسى پر كلام نازل كیا گیاہے؟ ) ﴿هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ﴾ (انبیاء: ۳)، (یہ تو تم ہی جیسا ایك انسان ہے)۔ چنانچہ الله پاك نے انہیں ابلیس اور اسكى ہلاكت كا قصہ سنایا جب اس نے تكبر كیا اور آدم علیہ السلام كے سجدے سے یہ كہہ كر انكار كردیا كہ میں تو اس سے بہتر ہوں۔ (الطبرى: ۲۱؍۲۳۹)\nہمارے نبى محمد صلی اللہ علیہ وسلم کے تعلق سے کفار قریش کے موقف اور ابلیس كے قصے میں كیا مناسبت ہے؟\nقَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ٧٩ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ٨٠ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ٨١\nابلیس نے روز قیامت تك كى الله سے مہلت مانگى تو اس بردبار ذات نے اسے مہلت دےدى جو اپنے نافرمانوں كےساتھ عذاب میں جلدى نہیں کرتا ہے اب جب وہ قیامت تک ہلاک نہ ہونے پر مطمئن ہوگیا تو اس نے سركشى وبغاوت كى اور كہنے لگا كہ میں یقیناً ان میں تیرے چنیدہ بندوں کے سواسب كو بہكادوں گا۔ (ابن كثیر: ۴؍۴۵)\nالله نے ابلیس كے مہلت كى مانگ پورى كردى تو اس سے آپ کوالله كى كونسى صفت کاپتہ چلتا ہے؟\nقَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ٨٢\nآدم علیہ السلام كے سبب جب اللہ نے ابلیس كو دھتكاردیا تو اس نے اس بات پر الله كى عزت كى قسم كھائی كہ وه بنى آدم کے سامنے خواہشات اور شہوتوں کو خوشنما انداز میں پیش کرکے اور ان پر شکوک و شبہات کی وار کرکے انہیں گمراہ کرےگا۔ (القرطبى: ۱۸؍۲۲۰)\nبنو آدم كو گمراه كرنے كے شیطانى وسائل كیا ہیں؟\nwords\nأَتَّخَذنَاهُم سِخرِيًّاكيا همارا ان كو حقير سمجھنا غلطي هے؟\nزَاغَتمائل هو گئے۔ ان پر نهيں گرے.\nبِالمَلَأِ الأَعلَىفرشتے.\nيَختَصِمُونَوه آدم كي تخليق ميں جھگڑا كرتے هيں.\nسَوَّيتُهُميں نے اس كے جسم كو كامل اور متناسق اعضاء كے ساتھ پيدا كيا.\nسَاجِدِينَتحيت و اكرام كا سجده.\nلَأُغوِيَنَّهُمميں ضرور ان كو گمراه كروں گا."],[458,"§ص ، الزمر\ndeeds\nجہنم کی آگ سے اللہ تعالیٰ کی پناه طلب كیجئے، یہ تو ابلیس كے پیروكاروں كا ٹھكانہ ہے.\nالله سے دعاء كیجئے كہ آپ كى توحید خالص اسى سے وابستہ رہے، اس میں کسی شرك وریاء كا شائبہ نہ ہو.\nسورج وچاند كى گردش اور اس میں موجود عبرتوں پر غور كیجئے.\nguid\nاگر آپ سے ایسا ہوسكے كہ اپنى دعوت كا بدلہ صرف اور صرف الله سے چاہیں تو ایسا ضرور كیجئے.\nالله تعالىٰ صرف خالص عبادت ہى قبول فرماتا ہے ، لہٰذا پورى كوشش كیجئے كہ آپ كے تمام اعمال خالص ہوں.\nجھوٹى باتوں اور الله ورسول اورمومنوں پر باتیں گھڑنے كى ہر طرح مذمت بیان كیجئے.\nrefl\nقُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ٨٦\nمسروق سے مروى ہے وه كہتےہیں كہ ہم عبد الله بن مسعود رضی اللہ عنہ کے پاس آئے تو انہوں نے كہا: لوگو! جسے كسى چیز كا علم ہو وه اسے بیان كرے اور اگر علم نہیں ہےتو صاف كہہ دے كہ الله بہتر جانتا ہے ، كیونكہ آدمی جس چیز کو نہیں جانتا ہے اس کے بارے میں“ الله اعلم” كہنا بھى علم ہے۔ اس لئے کہ الله نے تمہارے نبى صلی اللہ علیہ وسلم کو حکم دیا كہ آپ كہہ دیں كہ میں تم سے اس پر كوئى بدلہ نہیں چاہتا اور نہ ہى میں تكلف كرنے والا ہوں ۔ (ابن كثیر : ۴؍۴۵)\nعبد الله بن مسعود رضی اللہ عنہ نے اس آیت میں غور وفكر كركے طلباء كے آداب میں سے ایك ادب مستنبط كیا ہے ، بتائیے وه كیا ہے؟\nقُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٖ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ٨٦\nفرمانِ الٰہی (وما أنا من المتكلفين) (اور نہ ہى میں تكلف كرنے والوں میں سے ہوں)سے یہ قول اخذ كیاگیا ہے كہ آپ صلی اللہ علیہ وسلم جو دین لائے اس میں كوئى تكلف نہیں ہے۔ یعنى دینی فرائض و احکام میں کوئی مشقت نہیں ہے، اسلام میں سہولت وآسانى سے یہی مراد ہے۔ اور اس راحت وآسانی كى بنیاد یہ ہے كہ الله نے رسول صلی اللہ علیہ وسلم كى طبیعت اور روح ِ شریعت كے بیچ یک گونہ تناسب ركها ہے۔ (ابن عاشور: ۲۳؍۳۰۹)\nاس آیت كریمہ كى روشنى میں اسلام كى سہولت وآسانى بیان كیجئے.\nإِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٨٧\nیہ عظیم سورت پُرحکمت نصیحتوں پر مشتمل ہے ، اسى لئے الله نے سورت كے شروع میں قسم كھائى كہ یہ (قرآن) نصیحت والا ہے، اور آخر میں یہاں اسكى یہ صفت بیان كى گئى كہ یہ سارے جہان والوں كیلئے سراسر نصیحت ہے، نیز اللہ تعالیٰ اس سورت میں كثرت سے اس کا یاددلایا۔ جیسے فرمایا: (واذكر عبدنا)، (واذكر عبادنا)، (رحمة منا وذكرى) اور(هذا ذكر). (السعدى: ۷۱۷)\nكس امر کو اس سورت میں كثرت سے ذكر كیا گیا ہے ؟ نیز اس كا دو فائده بھى بیان كیجئے.\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١\nكلام متكلم كى صفت ہے، اور صفت موصوف كے تابع ہوتى ہے، لہٰذا جس طرح الله ہر ناحیہ سے كامل ہے، اس كا كوئى ثانى نہیں ، اسى طرح اس كا كلام بھى ہر اعتبار سے مكمل ہے جس کی كوئى نظیر نہیں ہے۔ لہٰذا قرآن کی صفت اور اس کے عظیم رتبے پر دلالت کے لئے اتنی ہی بات کافی ہے ۔ (السعدى: ۷۱۸)\nاس آیت میں قرآن كى عظمت كى خبر دى گئى ہے، اسے بیان كیجئے.\nأَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ\nابن العربى كہتےہیں كہ یہ آیت ہر عمل میں اخلاص نیت كے وجوب كى دلیل ہے۔ (القرطبى: ۱۸؍۲۴۶)\nدل كا وه کونسا عمل ہے جو اس آیت سے معلوم ہوتا ہے اور بتائیے كہ كیا وه واجب ہے؟\nإِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبٞ كَفَّارٞ ٣\nجب بنده الله پر جھوٹ باندھنے اور اس کو انكار كرنے میں ہمہ تن مشغول ہوجاتا ہے تو اس پر الله كى ناراضگى بڑھ جاتی ہے اور وه ہدایت سے كوسوں دور ہوجاتاہے جیسا كہ الله كا ارشاد ہے: الله تعالىٰ ان لوگوں كو كیسے ہدایت دےگا جو اپنے ایمان لانے اور رسول كى حقانیت كى گواہى دینے اور اپنے پاس روشن دلیلیں آجانے كےبعد بھی كافر ہوجائیں،ا لله ایسے بے انصاف لوگوں كو راه راست پر نہیں لاتا۔[آل عمران: ۸۶]۔ (ابن عاشور: ۲۳؍۳۲۴)\nآیت كى روشنى میں الله تعالىٰ پر جھوٹ كى خطرناكى بیان كیجئے.\nلَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ ٤\nالله تعالىٰ نےاپنے آپ كو اولاد اختیار كرنے سے پاك قرار دیا ہے، پھر اپنے لئے یكتائى كا وصف بیان فرمایا، اس لئے کہ اولاد كا ہونا وحدانیت كےخلاف ہے ، اسلئے بھی كہ اگر اسكى كوئى اولاد ہوتى تو اسى كى جنس سے ہوتى حالانكہ اس كى كوئى جنس ونسل نہیں ہے وه تو یك وتنہا ہے۔ اور الله نے اپنى صفت قہار بتائى ہے تاكہ اس سے ہمسر اور شریك كى نفى ہوجائے ، كیونكہ ہر چیز الله كے قہر وغلبے كے ماتحت ہے، پھر بھلا وه الله کی ساجھی دار كیسے ہوسكتى ہے! (ابن جزى: ۲؍۲۶۳(\nالله نے آیت كا خاتمہ(الواحد القهار)سے كیا ہے اور اس میں آیت كے مضمون سے ایك باریك سى مناسبت پائى جاتى ہے اسے بیان كیجئے۔\nwords\nأَجرٍجزاء ؛ اجرت / هدايت اور دعوت پر اجرت.\nالمُتَكَلِّفِينَالله تعاليٰ پر جھوٹ گھڑنے والے.\nنَبَأَهُقرآن كي خبر اور اس كي صداقت.\nمُخلِصًا لَهُ الدِّينَاس كي عبات و اطاعت ميں موحد.\nالدِّينُ الخَالِصُمكمل اور شرك سے محفوظ اطاعت.\nزُلفَىتقرب كا كام.\nلاَصطَفَىتو وه ضرور چن ليں.\nيُكَوِّرُوه داخل كرتا هے."],[459,"§الزمر\ndeeds\nاپنى ماں كےساتھ حسن سلوك كیجئے جس كےپیٹ میں الله نے آپ كى تخلیق فرمائى ہے.\nاپنے اوپر الله كے مسلسل وبے پایاں انعام واحسان كا شكر ادا كرتےہوئے كسى مسكین پر صدقہ كیجئے.\nرات میں قیام كیجئے اور یہ دعا مانگئے: “اَللّٰهُمَّ إِنِّيْ أَرْجُوْ رَحْمَتَكَ، وَأَخْشٰى عَذَابَكَ، اِنَّ عَذَابَكَ الْجِدَّ بِالْكُفَّارِ مُلْحِقٌ” اے اللہ! میں تیری رحمت کا امیدوار ہوں تیرے عذاب سے ڈرتا ہوں یقیناً تیرا سچا عذاب کافروں کو آپکڑے گا.\nguid\nآپ اس شخص كى طرح ہوجائیے جو خوشحالى میں اپنے رب كو اسى طرح یاد ركھتا ہے جیسے مصائب ومشكلات میں.\nالله نے اہل علم كا مقام ورتبہ بلند فرمایا ہے لہٰذا آپ بھى علماء كے زمرے میں شامل ہوجائیے.\nصبر كرنے والوں میں سے ہوجائیے اس لئے كہ ان كا اجر بے حساب ہے.\nrefl\nوَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ\nیہ وہى مضمون ہے جس كا ذكر الله نے سورۂ انعام میں كیا ہے ، الله نے پیدا كئے آٹھ نر وماده ، بھیڑ میں دو قسم ، اور بكرى میں دو قسم، اور اونٹ میں دو قسم اورگائے میں دو قسم\" [الانعام: ۱۴۳- ۱۴۴]۔ الله نے بندوں كى مصلحت میں اور بھى چوپائے اتارے ہیں پھر بھى بطور خاص ان آٹھ قسموں كو اس لئے ذكر كیا ہے كیونكہ ان کے فوائد بہت زیادہ اور عمومی ہیں اور ان کا ایک نمایاں مقام بھی ہے نیز انہیں كچھ ایسى خصوصیات حاصل ہیں جو دوسروں کو نہیں ہیں، جیسے ان كى قربانى ، ہدى، عقیقہ ، ان میں زكاة كا وجوب اور دیت میں انكى تخصیص ۔ (السعدى: ۷۱۹)\nان آٹھ قسم كے چوپایوں كو الله نے بطور خاص كیوں ذكر كیا ہے؟\nيَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ\nایك بناؤٹ كےبعد دوسرى بناوٹ ، یعنى انسان پہلےنطفہ پھر خون كا لوتھڑا ، پھر گوشت کے ٹکڑے کی شکل اختیار کرتا ہے ، یہاں تك كہ اسكى تخلیق پورى ہوجاتى ہے، پھر الله تعالىٰ اس میں روح پھونكتا ہے۔(ابن جزى: ۲؍۲۶۴)\nیہ آیت مخلوق كى كمزورى ولاغرى اور خالق كى قدرت بیان كرتى ہے، اسكى وضاحت كیجئے.\nيَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ\n“تین تین اندھیروں میں” ایك پیٹ كا اندھیرا، دوسرا رحم مادر كا اندھیرا اور تیسرا مشیمہ(وه جھلى یا پرده جس میں بچہ لپٹا ہوتا ہے) كا اندھیرا ، ۔ (الجزائرى: ۴؍۴۶۸)\nاس آیت كریمہ میں کون سے تین اندھیرے بیان کئے گئے ہیں؟\nذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ\nبندوں کو ان کی نعمت تخلیق وتدبیر اور امداد کی یاد دہانی کے لئے یہاں الله كى صفت ربوبیت كا ذكر کیا گیا ، اور یہی ربوبیت کا مفہوم ہے، نیز انكے كفران نعمت كى فضیحت كى تمہید بھی ہے جس كا بیان الله كےاس قول میں ہے: “اگر تم ناشكرى كروگے تو (یادرکھنا) الله تم سب سے بے نیاز ہے اور وہ اپنے بندوں کے لئے ناشکری کو ناپسند کرتا ہے”۔ (ابن عاشور: ۲۳؍۳۳۶)\nمذکورہ آیت كریمہ میں الله تعالىٰ كى صفت ربوبیت كے ذكر كا كیا فائده ہے؟\nأَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدٗا وَقَآئِمٗا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ\nان كى عبادت كیلئے رات كى تخصیص اس لئےہے كیونكہ رات كى عبادت ذكر الہى كیلئے دل كى یكسوئى اور ریا کاری سے دوری میں بڑى مددگار ہوتی ہے ، نیز الله كى عبادت كو نفس كى راحت اور نیند پر ترجیح دینے کی بین دلیل بھی ہوتی ہے ، اس لئے كہ رات میں آرام كى طلب زیاده ہوتى ہے اب ایسے میں بنده اگر عبادت كو ترجیح دیتا ہے تو اس كا دل یقیناً الله كى قربت کی محبت سے منور ہو اٹھے گا ۔ الله كا ارشاد ہے: “بیشك رات كا اٹھنا دل جمعى كیلئے انتہائى مناسب ہے اور بات كو بہت درست كردینے والا ہے” [مزمل: ۶]۔ (ابن عاشور: ۲۳؍۳۴۶)\nآیت كریمہ میں رات كو عبادت سے كیوں خاص كیا گیا ہے؟\nلِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ\nیہ نص عام ہے یعنی جو کوئی بھی نیک کام کرے گا دنیا میں اسے بھلائی (کشادہ رزق، امن امان، قلبی راحت)نصیب ہوگی مگر اس شخص کو یہ بھلائی میسر کیوں نہیں جسے کسی خطہ ارض میں ایمان كیوجہ سے ذلیل ورسوا اور پریشان كیا جارہاہے، تو اللہ نے اس شبہ كا جواب یہ كہہ كر دیا ہے كہ : “الله كى سرزمین وسیع ہے” الله نے بتایا كہ اسكى زمین تنگ نہیں ہے،لہذا جب تمہیں کسی جگہ اللہ کی عبادت سے روکاجائے تو ہجرت کرکے دوسری جگہ چلے جاؤ۔(السعدى: ۷۲۱)\nجب الله تعالىٰ نے یہ بتایا كہ دنیا میں ہر نیكى كرنے والے كا بدلہ نیكى ہے تو اسكے بعد یہ كیوں کہا گیا كہ اسكى سرزمین بہت وسیع ہے؟\nإِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ ١٠\nعلى رضی اللہ عنہ نے كہا: ہر فرمانبردار كو ثواب ناپ تول کر اور وزن كركے دیا جائےگا سوائے صبر كرنے والوں كے۔ انہیں بغیر ناپے تولے لپ بھربھرکر نوازا جائےگا۔ بیان کیا جاتاہے كہ آزمائش والوں كو لایا جائے گا ، ان كے لئے كوئى ترازو نصب نہیں ہوگا، نہ ہى كوئى دفتر كھولا جائےگا، بلكہ ان پر بلا حساب اجر كى نوازش ہوگى یہاں تك كہ ابتلاء وآزمائش والوں كى فضیلت دیكھ کر دنیا میں عافیت والے تمنا كریں گے كہ كاش كینچى سے انكا بدن كاٹا جاتا (تاکہ انہیں بھی یہ فضیلت ہاتھ آتی)۔ (البغوى : ۴؍۹)\nالله كےپاس صبر كرنے والوں كا بدلہ بلا حد و حساب كیسےہوگا؟\nwords\nثَمَانِيَةَ أَزوَاجٍآٹھ اقسام ؛ نر اور ماده / اونٹ ؛ گائے بھيڑ ؛ بكري.\nفِي ظُلُمَاتٍ ثَلاَثٍپيٹ كا اندھيرا؛ رحم كا اندھيرا؛ اور بچے كي تھيلي.\nفَأَنَّى تُصرَفُونَتم كيسے اس كي عبات سے رو گرداني كرتے هو.\nخَوَّلَهُاسے عطا كيا؛ انعام ديا.\nقَانِتٌالله تعاليٰ كا فرمانبردار.\nيُوَفَّىوه انهيں پورا پورا دے گا."],[460,"§الزمر\ndeeds\nاپنے خاندان کے کسی فرد کا نیك كام پر تعاون اس امید سے کیجئے كہ قیامت كےدن آپ سبھی کو کامیابی نصیب ہو.\nقرآن كى چند آیتیں غور سے سنیئے اور انہیں اپنى زندگى میں نافذكیجئے.\nكوئى درس یا مسجد میں كوئى تقریر توجہ سے سنیئے اور اسے عملی جامہ پہنائیے.\nguid\nاطاعت وعبادت میں اخلاص نبى كریم صلی اللہ علیہ وسلم كى صفات میں سےہے.\nعقلمند آدمى گناه كر نے سےپہلے آخرت کا ہولناك عذاب یاد كرتا ہے.\nلوگوں میں سب سے بڑے خسارے میں وه ہے جو بروز قیامت اپنے آپ كو اور اپنے اہل وعیال كو نقصان میں ڈال دے.\nrefl\nقُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصٗا لَّهُ ٱلدِّينَ ١١ وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ ١٢\nاگر پوچھا جائے كہ (أمرت) كا عطف (أمرت) پر كیسے جائز ہوا جبكہ دونوں كا ایك ہى معنى ہے؟ تو اس كا جواب یہ ہے کہ پہلے میں عبادت اور اخلاص كا حكم ہے، جبكہ دوسرے میں اسلام كى طرف سبقت كا حكم ہے، پس دونوں كا معنى الگ الگ ہے۔(ابن جزى: ۲؍۲۶۶)\nان آیتوں میں (أمرت) فعل كى تكرار کے ذریعہ دو الگ الگ چیزوں پر ابھارا گیا ہے، بتائیے وه دونوں كیا ہیں؟\nوَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ ١٢\nچونکہ میں لوگوں کو ان کےرب كى طرف بلانے اور راہِ حق بتلانے والا ہوں۔ لہذا میرا یہ عمل اس بات كا متقاضی ہے كہ میں جس كا حكم دے رہاہوں پہلے اسے خود بجا لاؤں اور پہلا فرمانبردار بن جاؤں ، اور ضرورى ہے کہ یہ كام محمد صلی اللہ علیہ وسلم اور انكے پیروكاروں كى جانب سے بھی انجام پائے۔(السعدى: ۷۲۱)\nدین كو مضبوطى سے پكڑنے پر قرآن كریم ابھارتا ہے ، یہ چیز آپ آیت كریمہ كى روشنى میں بیان كیجئے.\nقُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nیعنى ایك دوسرے سے جدا ہوجائیں گے اور كبھى مل نہیں پائیں گے ، خواه انكے اہل خانہ جنت میں چلے جائیں اور یہ خود جہنم میں ، یا پھر سب كا ٹھكانہ جہنم ہى قرار پائے۔ لیكن ملاقات نہیں ہوگى اور نہ ہى انہیں كوئى خوشى ملےگى۔(ابن كثیر: ۴؍۴۹)\nاگر بروز قیامت نافرمان لوگ اپنے اہل وعیال سمیت جہنم میں چلےجائیں تو كیا انہیں اپنے اہل و عیال کے ساتھ یکجا ہونے میں کوئی خوشی ہوگی؟\nٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ\nابن عباس رضی اللہ عنہما نے كہا كہ وه ایسا شخص ہے جو اچھى اور برى دونوں باتیں سنتا ہے پھر اچھی بات کو ہی بیان کرتاہے اور برى بات سے باز رہتا ہے اسے كسى سے بیان نہیں كرتا۔ اور یہ بھى كہا گیا ہے كہ اس سےمراد وه لوگ ہیں جو قرآن کے علاوہ اور بھی باتیں غور سے سنتےہیں لیکن اتباع قرآن ہى كى كرتےہیں۔ (القرطبى: ۱۸؍۲۶۰)\nباتوں کو بغور سماعت کرکے ان میں سے اچھی کی پیروی کا کیا طریقہ ہے.\nٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ ١٨\n(القول) جنس ہےجو ہر بات كو شامل ہے، وہ ہربات دھیان سے سنتےہیں تاكہ تمیز كرسكیں كہ كسے ترجیح دینا اور اپنانا ہے اور كس سے اجتناب كرنا ہے،لہٰذا ان کی عقلمندی اور دانشمندی ہے کہ وہ صرف اچھى بات كى اتباع كرتےہیں ، اور مطلق طور پربھلی بات الله اور اسكے رسول كا كلام ہے، جیسا كہ الله نے اس سورت میں فرمایا: (اللَّهُ نزلَ أَحسَنَ الحَدِيثِ كِتَابًا مُتَشَابِهًا)... اس لئے جوشخص اچھى برى باتوں میں فرق نہیں كرپاتا وه صحیح عقل كا حامل نہیں ہے، یا جو تمیز تو كر لے لیكن اس کی شہوت اس کے عقل پر اس طرح غالب آجائے کہ عقل خواہش كےتابع ہوکر رہ جائےکہ اچھى بات كو ترجیح دینے کے قابل نہ رہے تو ایسے شخص کو بے وقوف اور ناقص العقل کہاجائے گا۔(السعدى: ۷۲۲)\nآپ كسى كےبارے میں كیسے فیصلہ كریں گے كہ وه متوازن اور سنجیدہ عقل والا ہے؟\nٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ ١٨\nوه قرآن کو بغور سنتےہیں ،پھر اس کے اچھی باتوں کو عملی تطبیق دیتے ہیں جیسے عفو ودرگزر سے كام لیتےہیں جو یقیناً بدلہ و انتقام سے کہیں بہتر ہے یا اس طرح کے دیگر اچھے کام۔(ابن جزى: ۲؍۲۶۷)\nاس آیت كى وارد تفسیر كى روشنى میں انسان بھلى بات كى اتباع كیسے كرےگا؟\nأَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ ١٩\nیہاں “انقاذ” كافعل نبى كریم صلی اللہ علیہ وسلم كى حالت كو اس شخص كى حالت سے تشبیہ دینے كیلئے لایا گیا ہے جو چاروں طرف سے گہری آگ میں گرنے والے كو بچانے كى پورى كوشش كرتاہے، آپ صلی اللہ علیہ وسلم كا حال یہ تھا كہ وه لوگوں كى ہدایت كے بڑے حریص تھے اور لوگوں كا عالم یہ تھا كہ وه موجبات وعید كے كاموں میں لت پت تھے۔(ابن عاشور: ۲۳؍۳۷۷)\nآیت كریمہ كى روشنى میں بتائیے كہ نبى كریم صلی اللہ علیہ وسلم لوگوں كى ہدایت كے كتنے حریص تھے؟\nwords\nظُلَلٌ مِنَ النَّارِجهنم كي آگ كے طبقے سائبان كي طرح.\nالطَّاغُوتَالله تعاليٰ كي علاوه معبود.\nوَأَنَابُواتوبه و طاعت گزاري كے ساتھ رجوع إلي الله.\nفَسَلَكَهُ يَنَابِيعَاسے بهتے چشموں ميں داخل كرديا.\nيَهِيجُوه خشك هو جاتا هے.\nحُطَامًاچورا چوا ؛ توڑاهوا."],[461,"§الزمر\ndeeds\nصبح وشام كے اذكار پڑھا كیجئے، کیونکہ اس سے انشراح صدر حاصل ہوتا ہے.\nكوئى ایسا كتابچہ پڑھئے جس كا تعلق قرآن پڑھتےوقت خشوع وخضوع كے اسباب ووسائل سے ہو.\nآج ہی سے قرآن كریم پر زیاده سے زیاده غور وفكر كے حریص بن جائیے.\nguid\nاچھى طرح سے جان لیجئے كہ ہدایت صرف الله كے ہاتھ میں ہے، اسكے علاوہ کسی دوسرے کے اختیار میں نہیں ہے، لہٰذا ہر وقت ہدایت اسى سےمانگا كیجئے.\nجو دنیا میں الله كى نافرمانى سے نہیں بچےگا تو وہ قیامت كے دن اپنے آپ کو دردناك عذاب سے ہرگز بچا نہیں پائے گا.\nیقین مانیئے كہ سب كو فنا كےگھاٹ اترنا ہے ، پھر جب معاملہ ایسا ہے تو آج ہى اس دن کے لئے تیار ہوجائیے.\nrefl\nأَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ\nقبول ِ اسلام پر دلالت كیلئے “شرح”كے كلمہ كو اس لئے ترجیح دى گئى ہے، کیونکہ اسلامى تعلیمات اور اسكے آداب واخلاق مسلم کو قبولِ اسلام اور اپنے رب سے راضی ہونے کی وجہ فرحت و مسرت فراہم کرتے ہیں، وہ مشكلات ومصائب كو معمولى سمجھنے لگتا ہے، كیونكہ اسے پختہ یقین ہوتا ہے كہ وه حق پر ہے ، تكالیف پر ثواب پانے والا ہے، دنیا وآخرت میں اپنے رب كى رحمت سے پرامید ہے اور اس لئے بھی کہ اس کا قلب و جگرشک و شبہ کی آمیزش سے پاک ہوتا ہے۔ (ابن عاشور: ۲۳؍۳۸۰)\nقبول اسلام پر دلالت کرنے کے لئے کلمہ شرح کے انتخاب کی وجہ بتائیے؟\nفَوَيۡلٞ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ ٢٢\nمالك بن دینار كہتےہیں كہ كسى بھى بندے كى سب سے سخت سزا یہ ہے كہ اس كا دل سخت ہوجائے ، اور الله تعالىٰ جس قوم پر غضبناك ہوتاہے اس سے رحمت وشفقت چھین لیتاہے۔ (البغوى: ۴؍۱۲)\nبندے کے لئے سب سے بڑى سزا كیا ہے؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ\nکیونکہ کفار و منافقین کے اوپر سختی کرنا اللہ کے لئے نرم ہوجانا ہے۔ جیساکہ اللہ والوں پر نرمی کرنا اللہ کی خشیت میں سے ہے۔ اور شروع میں اللہ نے اپنے نبی کو کفار و منافقین کے عذر کو دورکرنے اور ان کے اصرار کو بیان کرنے کے لیے ان کے اوپر نرمی کرنے کا حکم دیاتھا ۔ چنانچہ جب نرمی اپنی انتہا کو پہنچ گئی تو وہ سختی اور شدت میں بدل گئی۔(البقاعی: ۲۰؍۲۰۶)\nکسی انسان کو کافروں اور منافقوں پر سختی کرنے کا حکم کب دیا جائے گا.\nٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ\nقرآن كے (أحسن الحديث) ہونے كا معنى یہ ہے كہ یہ سب سے افضل خبر ہے، كیونكہ یہ افضل ترین خبروں پر مشتمل ہے، جیسے مفید معانى، ایمان وتشریع اور استدلال كے جامع اصول ، دنیا جہان كى عظمتوں پرآگاہى، عقل و انسانی تخلیق كے عجائبات، آداب واخلاق كى اشاعت ، اور صحیح استدلال کے لئے غور وفکر كا مطالبہ ۔ نیز معجزے كے حد كو پہونچے ہوئے اس کے الفاظ کی فصاحت اور معانی کی بلاغت۔ (ابن عاشور: ۲۳؍۳۸۵)\nمختصراً بتائیے كہ قرآن كو احسن الحدیث كیوں كہاگیا ہے؟\nٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ\nیعنى اسكے قصے واحكام، وعدے ووعید، اچھوں اور بروں كى صفات دہرائى جاتى ہیں۔ اسى طرح الله كے اسماء وصفات بار بار سنائےجاتےہیں۔اور دلوں كیلئے ان معانى کو وہى مقام حاصل ہے جو درختوں كے لئے پانى كو ، چنانچہ جس طرح درختوں كو زیاده دن تك سیراب نہ كیا جائے تو وہ پژمردہ ہوجاتے ہیں ،بلکہ بسا اوقات سوكھ كر ضائع بھى ہوجاتے ہیں اور اگر پانى سے انہیں برابر سیراب كیا جاتا رہے تو ہرابھرا رہتےہیں اور مختلف قسم كے مفید پھل دیتے رہتے ہیں ، ٹھیک یہی حال دل كا بھی ہے ،وہ ہمیشہ اس بات کا محتاج ہے کہ اس پر بار بار کلامِ الٰہی کے معانی پیش کئے جائیں۔اسى طرح یہ بھى بہت اہم ہے كہ قرآن پڑھنے اور اسكے معانى پر غور كرنے والا تمام قرآنى مقامات پر تدبر سے کام لینے میں قطعی غفلت نہ برتے۔ ایسا كرنے سے آدمی کو بہت سى بھلائیاں ملیں گی اور بہت سارا نفع حاصل ہوگا۔ (السعدى: ۷۲۳)\nقرآن کریم کے بہت سارے مقامات پر كچھ معانى كى تكرار ہے، بتائیے كہ اس میں كیا حكمت ہے؟\nتَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ ٢٣\nاگر یہ كہا جائے كہ پہلے جلدوں(چمڑوں) كا علاحده ذكر کیوں آیا پھر اس كے بعد جلدوں (چمڑوں) كے ساتھ دلوں كا تذكرہ کیوں كیا گیا؟ تو اس كا جواب یہ ہے کہ پہلے جب الله نے (تقشعر) كہا تو جلدوں(چمڑوں) كا تنہا ذكر كیا، اسلئے كہ رونگٹوں كا كھڑا ہونا صرف جلد كى صفت ہے۔ اور جب الله نے (تَلِيْنُ) كا كلمہ ذكر كیا تو اس كے ساتھ چمڑا اور دل دونوں كا ذكر كیا ؛ كیونكہ نرم ہونا دل اور چمڑا دونوں كى صفت ہے، یعنى خوف سے پہلے رونگٹے كھڑے ہوئے پھر امید سے نرم پڑگئے۔(ابن جزى: ۲؍۲۶۸)\nالله تعالىٰ نےپہلے صرف جلدوں كا تذكرہ كیا ، پھر اسكے بعد جلدوں اور دلوں كو ایك ساتھ کیوں ذكر فرمایا؟\nوَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ١١\nمثال بیان کرنے کی وجہ یہ ہے کہ ایک مؤمن کا کسی کافر کے ساتھ تعلق رکھنے سے کوئی نقصان نہیں ہوتاہے بشرطیکہ مومن کافر کے کفر وعمل میں شریک نہ ہو۔ لہٰذا کسی دوسرے کی معصیت اطاعت گذار مؤمن کوآخرت میں کچھ بھی نقصان نہیں پہنچائے گی ، گرچہ مومن کو دنیا میں اس سے نقصان ہو سکتا ہے اس عذاب کی وجہ سے جو زمین والوں پر اللہ کے حکم کی خلاف ورزی کی وجہ سے نازل ہوتا ہے جو کہ سب پر عام ہوتا ہے۔ یہی وجہ ہے کہ فرعون کی بیوی کو اس کے ساتھ تعلق رکھنے کی وجہ سے کوئی نقصان نہیں ہوا جبکہ وہ کافروں میں سب سے بڑا کافر تھا ۔(ابن قیم: ۳؍۱۷۰)\nکافر کے ساتھ تعلق میں مبتلا مومن پر کیا واجب ہے؟\nأَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ\nاسے دردناك عذاب لاحق ہوگا پھر وه بدن كے سب سے محترم حصے چہرے سے بدترین عذاب كو ہٹانے كى كوشش كرےگا؛ حالانکہ چہرہ ایسا نازک حصہ ہے جس پر معمولی عذاب بھی اثرانداز ہوجاتا ہے۔كیونكہ اس كے دونوں ہاتھ اور دونوں پاؤں بندھے ہوئےہونگے۔(السعدى: ۷۲۳)\nجہنمیوں كا اپنے چہروں كے ذریعے عذاب سے بچاؤ كرنے كا سبب كیا ہے؟\nوَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ٢٧\nاعجاز قرآن کے مختلف گوشوں میں سے ایک عظیم گوشہ امثال قرآن کی بلاغت میں غور و تدبر کرنے کے واسطے مخاطبین کی بصیرتی توجہ مبذول کرنے کے لئےقرآن كریم كےدیگر امتیازات وخصوصیات كے بیچ بطور خاص قرآنى مثالوں کا تذکرکیا گیا ہے ، کیونکہ عرب كے فصحاء وبلغاء امثال کی عمدگی میں منافست كرتےتھے۔(ابن عاشور: ۲۳؍۳۹۷)\nبطور خاص قرآن كى مثالیں كیوں ذكر كى گئى ہیں؟\nwords\nمَثَانِيَجس ميں احكام و قصص اور حجج مكرر بيان هوئے هيں.\nتَقشَعِرُّكانپ جانتے هيں/ رونگٹے كھڑے هو جاتے هيں.\nتَلِينُوه نرم پڑ جاتے هيں / مطمئن هو جاتے هيں.\nعِوَجٍاضطراب ؛ ٹيڑھ پن ۔ ملاوٹ.\nمُتَشَاكِسُونَمتنازع / جھگڑا كرنے والے."],[462,"§الزمر\ndeeds\nآج سے آپ سچ بولنے كے حریص بن جائیے خواہ اس کا تعلق حقیقت سے ہو یا مزاح سے.\nیہ دعا پڑھئے: (اَللّٰهُمَّ يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلٰى دِيْنِكَ) اے اللہ! اے دلوں کو بدلنے والے، میرے دل کو اپنے دین پر ثابت رکھ.\nیہ دعا پڑھئے: (حَسْبِيَ اللّٰهُ لَا اِلٰهَ اِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرشِ الْعَظِيْمَ) میرے لئے اللہ تعالیٰ کافی ہے جس کے سوا کوئی معبود برحق نہیں ہے، اسی پر میرا بھروسہ ہے، اور وہی عرش عظیم کا رب ہے.\nguid\nالله عزو جل كا تقوىٰ اپنانے میں سچائى كى بڑى اہمیت ہے، اس لئے اپنے اور غیروں کے ساتھ سچائی کی راہ اختیار کرنے والوں میں سے ہوجائیے.\nاگر حقیقى معنوں میں آپ الله کے بندہ بن جائیں تو الله تعالىٰ آپ كى حفاظت وضرورت كیلئے كافى ہوجائےگا.\nہمت پست كرنے والوں سے جب بھى آپ كا سامنا ہو تو الله سے مزید خوف کھائیے.\nrefl\n۞فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ ٣٢\nکفار مشرکین سب سے بڑے ظالم لوگ ہیں کیونکہ انہوں نے طرح طرح كے سنگین ظلم انجام دئیےہیں، جیسے الله كی صفات میں جھوٹ بول کر رب پاک کی بے حرمتی کرنا اور اس کی ذات پر ظلم و زیادتی کرنا، ،اور ایسا ظلم اس لئے ہے کیوں کہ انہوں نے اس کی ربوبیت میں دوسروں کو اس کا ساجھی اور شریک ٹھہرایا ہے۔ نیز انہوں نے حرمت ربوبیت کی پامالی اس طرح بھی کہ انہوں نے اللہ تعالیٰ پر یہ جھوٹ گڑھا کہ جو کچھ ان کے مشرکانہ عقائد ہیں ان سب كا حكم خود الله نے دیا ہے، رسول صلی اللہ علیہ وسلم كو جھٹلاكر ان پر ظلم ڈھانا، قرآن پر ستم اس كى طرف جھوٹ وباطل كى نسبت كرناجیسے کہانت و جادو وغیرہ، مومنین پر ظلم، انہیں تكلیف پہنچانا، كائنات كى سچائى پر ظلم، ان كے حقائق بدلنا او ر انہیں خراب كرنا، بلكہ خود ان کا اپنےآپ پر بھى ظلم كرنا اوردائمى عذاب میں خود كو جھونك دینےكاسامان كرنا وغیرہ ۔ (ابن عاشور: ۲۴؍۵)\nظلم كى وہ بعض قسمیں ذكر كیجئے جنكى وجہ سے مشركین سب سے بڑے ظالم قرار پائے.\nوَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ٣٣\nآیت میں مذکور دونوں خوبیوں کو اپنانے والے لوگ متقی و پرہیزگار ہیں اس لئے كہ تقوىٰ كى تمام صفات کا تعلق دین حق کی طرف رہنمائی اور اسكى تصدیق كرنے سے ہے۔ (السعدى: ۷۲۴)\nدین حق کی طرف رہنمائی کرنے اور اس کی تصدیق سے تقوىٰ كا كیا تعلق ہے؟\nأَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ\nرسول الله صلی اللہ علیہ وسلم كو عبودیت كى صفت سے متصف كرنے اور اسم جلالہ كى جانب اس كى اضافت میں ایك عظیم حکمت یہ ہے كہ الله نے اپنے رسول كو یہ نسبت عطاکرکے شرف بخشا ہے اور یہ یقین دلایا ہے کہ وہ اپنے رسول كو دشمنوں كے حوالے نہیں كرےگا۔ (ابن عاشور: ۲۴؍۱۳)\nالله نے اپنے نبى صلی اللہ علیہ وسلم كو اس آیت میں ایك عظیم شرف بخشا ہے اسے بیان كیجئے.\nأَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ\nالله كےاس فرمان : (أَلَيسَ اللَّهُ بِكافٍ عَبدَهُ) (كیا الله اپنے بندے كیلئے كافى نہیں ہے؟) سے نبى كے نفس كو تقویت ملتى تھی، کیونکہ كفار قریش آپ صلی اللہ علیہ وسلم كو بتوں سے ڈراتے تھے اور كہتےتھے كہ: محمد ! تم بتوں كو برا بھلا كہہ رہےہو ہمیں ڈر ہے کہ وہ تمہیں جنون یا کسی اور بیمارى میں مبتلا کردیں گے، تب یہ آیت نازل ہوئى۔ (ابن عطیہ: ۴؍۵۳۲)\nجب كسى مومن كو مخلوق سے ڈرایا جائے تو اس كا كیا موقف ہوناچاہئے؟ اسے آیت كى روشنى میں واضح كیجئے.\nأَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ ٣٧\nجب وه الله كے مذكوره ان دونوں اوصاف كا اقرار كرتےہیں تو وه یہ بھى بالیقین مان لیں كہ اپنے غلبے كى بنیاد پر وہ اپنے بندے كیلئے كافى ہے۔لہٰذا كوئى بھى اسكے بندے كی ایذا رسانى پر قادر نہیں ہے، نیزوه ان سے انتقام لےگا جو اسكے بندے كو ستاتےہیں۔ (ابن عاشور: ۲۴؍۱۵)\n(عزيز ) اور (ذي انتقام)كى صفت سےآیت كے خاتمے كى مناسبت بتائیے.\nقُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ ٣٩ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ٤٠\nجب الله تعالیٰ نے کفار ومشرکین کو انتہائى درجے كى نصیحت كردى، اعلى ترین دلیل پیش كردى اور اپنے رسول کوحد درجہ ثبات قدمی بخش دی، پھر بالیقین رسول پاک صلی اللہ علیہ وسلم کو حکم دیا کہ ان سے اس بات پر صلح کرلیں کہ عنقریب اللہ کی مدد آئے گی اور انہیں انکے لئے تیار شده خسارے ونقصان کی وعید سنادیں ۔ (ابن عاشور: ۲۴؍۱۹)\nاپنے ماقبل آیات سے اس آیت کریمہ کی کیا مناسبت ہے؟\nمَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ٤٠\n(عذاب يخزيه) یعنی ایسا عذاب جواسے رسوا كردیگا ، ذلیل كردےگا ، قتل ، قید، قحط اور بھوك وغیره كےذریعے اسكى ناك خاك آلود ہوگى اور بالفعل مشركین كو مكہ اوربدر كےمقام پر یہ عذاب بھگتنا پڑا ۔ الله كےاس قول: (ويحل عليه عذاب مقيم) سے مراد آخرت میں جہنم كا عذاب ہے، الله كے ان دونوں عذاب سے ہم پناه مانگتے ہیں ، یعنى دنیا میں ذلت ورسوائى كا عذاب اور آخرت میں جہنم كا عذاب ۔ (الجزائرى: ۴؍۴۹۰)\nرسوائى كے عذاب اور دائمى عذاب میں كیا فرق ہے؟\nwords\nبِالصِّدقِحق كے ساتھ.\nمَثوىًٹھكانا/ مسكن.\nحَسبِيَميرے ليے كافي هے.\nمَكَانَتِكُمتمهاري وه حالت جس پر تم اپنے ليے راضي هو.\nيُخزِيهِيوه اسے ذليل كرتا هے."],[463,"§الزمر\ndeeds\nیہ دعا پڑھئے: (اَللّٰهُمَّ أَسْلَمْتُ نَفْسِىْ إِلَيْكَ، وَفَوَّضْتُ أَمْرِیْ إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِیْ إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ، وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِیْ أَنْزَلْتَ، وَنَبِيِّكَ الَّذِیْ أَرْسَلْتَ) ’’اے اللہ! میں نے اپنے آپ کو تیرے حوالے کیا، اور اپنا معاملہ تیرے سپرد کیا، اور اپنی پشت تیری ہی طرف جھکادی تیری طرف رغبت کرتے ہوئے اور تجھ سے ڈرتے ہوئے، نہ تیرے علاوہ کوئی جائے پناہ ہے اور نہ تجھ سے بھاگ کر جانے کی کوئی جگہ ہے، میں تیری نازل کردہ کتاب اور تیرے بھیجے ہوئے نبی پر ایمان لایا.\nمختلف ماثور اذكار كے ذریعے برابر الله كو یاد كرتےرہئیے.\nآپ كو ئى ایسا عمل طے كیجئے جس كى صحت كےبارے میں آپ كو تردد ہو، پھر اسكا حكم كسى عالم سے پوچھئے.\nguid\nایك گھنٹہ غور وفكر كرنا، بلا غور كے پورى رات قیام سے بہتر ہے جیسا كہ بعض سلف سے یہ بات مروى ہے.\nشفاعت تمام كى تمام الله كےہاتھ میں ہے، لہذا اسے الله ہى سے طلب كیجئے.\nآپ اپنے عمل میں اخلاص نیت اور سنت كى موافقت كے حریص بنئے.\nrefl\nٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا\nالله تعالىٰ نے خبر دى كہ وه روحوں كو قبض كر لیتاہے، یہاں خود اپنى جانب فعل كى نسبت اس بات كے منافى نہیں ہے كہ الله نے قبض روح كى ذمہ دارى ملك الموت اور ان كے اعوان وانصار كو دى ہے۔ كیونكہ الله تعالىٰ كچھ چیزوں كى نسبت اپنى طرف اس اعتبار سے كرتا ہے كیونكہ وہى ان اشیاء كا خالق و مدبر ہے، اور كبھى اسباب كى طرف ان كى نسبت كرتاہے ، اس اعتبار سے كہ یہ الله كى سنت رہی ہے كہ اس نے ہر كام كیلئے كچھ اسباب متعین كر ركھے ہیں۔ (السعدى: ۷۲۵)\nیہاں ہے کہ جانداروں كو الله وفات دیتاہے، كچھ مقامات پر ہے كہ ملك الموت وفات دیتےہیں ، آپ ان میں كیسے تطبیق دینگے؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ٤٢\nیعنى یہ الله كى كامل قدرت كى نشانیاں ہیں ، اس طور پر كہ كس روح كو چھوڑنا ہے ، كسے قبض كرلینا ہے اس میں كبھى چوك نہیں ہوتى ۔ مقاتل كہتےہیں: موت كے بعد دوباره اٹھائے جانے كے سلسلے میں غور وفكر كرنے والوں كیلئے اس میں نشانیاں ہیں، یعنى سوئى ہوئى نفس كو وفات دینا اور پھر جسے چاہنا اسكى روح واپس لوٹا دینا ، دوباره اٹھائے جانے پر واضح دلیل ہے۔ (البغوی ۴؍۱۹)\nنیند میں روح روك لینا پھر اسے چھوڑ دینا دوباره اٹھائے جانےپر كس طرح دلالت كر تاہے؟\nأَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ ٤٣\nشفاعت معنوى چیز ہے، اسكى ملكیت كا مطلب ہے اسكا جواب دینا۔اس كلام میں مشركین كا مذاق اڑایا گیا ہے کہ وه كیسے سفارش كرےگا جو سمجھتا تك نہیں ہے؟ غیر عاقل سے اس بات كا تصور ہى نہیں كیا جاسكتا كہ اس كو سفارش كا خیال آئے چہ جائے كہ وه کسی کی شفاعت طلبی پر طرف متوجہ ہو۔ لہٰذا ایسے كوسفارشى بنانا تو سراسر نادانى ہے۔(ابن عاشور: ۲۴؍۲۷)\nبتوں كو سفارشى بنانے میں كس طرح سے مشركین كا استہزاء ہے؟\nقُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nیہاں یہ صراحت ہے کہ شفاعت صرف اور صرف الله كیلئے ہے، جیسا كہ دوسرى جگہ الله نے فرمایا:﴿مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦ﴾ كون ہے جو الله كےپاس اسكى اجازت كے بغیر شفاعت كرے۔ (البقره: ۲۵۵)۔ چنانچہ اللہ کی اجازت کے بغیر کوئی کسی کی سفارش نہیں کرسکتا۔ (القرطبی ۱۸؍۲۸۹)\nكیا الله كے علاوه كوئى اور شفاعت كا مالك ہے؟\nوَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ\nاس كا معنى یہ ہے کہ كفار الله كى توحید كو ناپسند كرتےہیں اور شرك سے لگاؤ ركھتےہیں، اور (اشمأوت) كا معنى ہے كہ شدید نفرت وكراہت كیوجہ سے انكے دل گھٹن محسوس كرتےہیں۔ (ابن جزى: ۲؍۲۷۱)\nآپ اس آیت سے یہ استدلال كیسے كریں گے كہ توحید دل كےاعمال كو بھی شامل ہے؟\nقُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ٤٦\n(فاطر السماوات والأرض) كى صفت الله كى صفتِ قدرت كا احساس دلاتى ہے، اور اسے علم كى صفت پر اسلئے مقدم كیا گیا ہے كیونكہ لوگوں كو الله كى قدرت كا احساس اسكے علم سےپہلے ہوتا ہے، اور اسلئے بھى كہ قدرت اور حكم میں گہرى مناسبت ہے،کیونکہ حکم میں قہر و غلبہ کا مفہوم ہے، اور قدرت اسی كا نتیجہ ہے۔ (ابن عاشور: ۲۴؍۳۱)\nآیت كریمہ كى اپنے ماقبل سے كیا مناسبت ہے؟\nوَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ ٤٧\nمجاہد كا قول ہے كہ وه لوگ كچھ ایسے كام كئے ہوں گے جنكے بارے میں ان كا خیال ہوگا كہ یہ بھلے ہیں پھر اچانك انہیں معلوم ہوگا كہ یہ سب تو برےكام تھے۔ اور یہ بھى ہوسكتا ہے کہ وه اس خوش گمانی میں رہےہوں كہ انہیں بغیر توبہ کے معاف كردیا جائے گا ۔ (وبدا لهم من الله ما لم يكونوا يحتسبون) اور الله كى طرف سے وه ظاہر ہوگا جس كا انہیں گمان نہیں تھا، یعنى كہ وه جہنم میں داخل ہوں گے۔ سفیان ثورى نے اس آیت كےبارے میں كہا: ریاكاروں كیلئے ہلاكت ہے، ان كےلئے تباہى ہے، یہ انہیں كى نشانى اور انہیں كى كہانى ہے۔ عكرمہ بن عمار نے كہا: محمد بن المنكدر اپنى موت كےوقت بہت زیادھ گھبراہٹ كےشكار تھے ، جب ان سے اس كى وجہ پوچھى گئى تو انہوں نے جواب دیا كہ مجھے قرآن كى ایك آیت سے ڈر لگ رہاہے: (وبدا لهم من الله ما لم يكونوا يحتسبون) بس مجھے ڈر ہے كہ كہیں مجھ پر وه چیز ظاہر نہ ہو جس كا میں نے گمان تك نہیں كیا تھا۔ (القرطبى: ۱۸؍۲۸۹)\nكیا یہ ممكن ہےكہ جسے آپ بھلائی سمجھ رہے ہیں وه بروز قیامت برائى ٹھہرے؟\nwords\nيَتَوَفَّىوه قبض كرتا هے.\nاشْمَأَزَّتوه نفرت سے بھاگے.\nفَاطِرَخالق / پيدا كرنے وال.\nالغَيْبِ والشَّهَادَةِخفيه اور اعلانيه.\nيَحْتَسِبُونَوه گمان ركھتے هيں."],[464,"§الزمر\ndeeds\nاپنے اوپر الله كى تین بڑى بڑى نعمتیں یاد كیجئے ، پھر ان پر الله كا شكر ادا كیجئے.\nیہ دعا پڑھئے: (اَللّٰهُمَّ اغْفِرْ لِىْ ذَنْبِىْ كُلَّهٗ دِقَّهٗ وَجِلَّهٗ وَأَوَّلَهٗ وَآخِرَهٗ وَعَلَانِيَتَهٗ وَسِرَّهٗ) ‘‘اے اللہ! میرے چھوٹے بڑے، اول و آخر اور ظاہری و باطنی سارے گناہوں کو بخش دے.\nدعا كیجئے كہ الله نے آپ كو دنیا كى جو نعمتیں بخشى ہیں انہیں آپ كى تواضع اور رب سے قربت كا ذریعہ بنادے، نیز دنیاوى نعمتوں كے فتنوں سے پناه مانگئے.\nguid\nنعمتوں كےذریعے الله كى آزمائش سےآپ چوكنا رہیئے، كیونكہ بہت سے ایسے لوگ ہیں جنہیں نعمتیں حاصل ہیں، وہ فتنے میں ہیں، انہیں ڈھیل دی جارہی ہے، اور انہیں اسكى خبر ہى نہیں.\nالله كے تمام فیصلوں سے راضى ہوجائیے، كیونكہ وہی اللہ ہے جو جس کی رزق میں چاہتا ہے کشادگی فرماتا ہے اور جس کی رزق میں چاہتا ہے تنگی دیتا ہے.\nجب بکثرت گناہوں کا ارتکاب کرنے والوں کو رحمت و بخشش کی خوشخبری سنائی گئی ہے، تو دوسروں کے لئے یہ خوش خبری بدرجۂ اولیٰ موجود ہے لہٰذا توبہ کرنے میں جلدی کیجئے.\nrefl\nوَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ٤٨\n(عملوا) فعل پر (كسبوا)كو ترجیح دى گئى ہے، یہ بتانے كیلئے كہ عذاب سے انكى براءت ممكن نہیں ہے ، كیونكہ عذاب كے اسباب تو خود انكے اختیار كرده ہیں، جیسا کہ الله نے اپنے اس قول میں بیان فرمایا ہے: ﴿وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ﴾ ظالموں سے كہاجائے گا كہ اپنے كئےكا وبال چكھو۔ (الزمر: ۲۴) یہاں بھی (تَعْمَلُوْنَ) كےبجائے (تَكْسِبُوْنَ) كہا گیا ہے۔ (ابن عاشور: ۲۴؍۳۴)\nآیت میں (عَمِلُوْا)كےبجائے(كَسَبُوْا ) كیوں كہاگیا ہے؟\nفَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا\nاس آیت میں ایك سچائى بیان كى گئى ہے، كہ كفار قریش الله كےرب ہونے پر ایمان ركھتےتھے لہٰذا وه ان کمیونسٹوں سےزیاده بہتر تھے جو اللہ تعالیٰ پر ایمان نہیں رکھتے۔ نیز کفار قریش آج كے كچھ جاہل مسلمانوں سے بھی بہتر تھے كیونكہ وه شدت كى گھڑى میں خالص الله كو پكارتےتھے جبكہ یہ جاہل مسلمان تو شدت اور خوشحالى دونوں میں الله كا شریك ٹھہراتےہیں، اولیاء اور مردوں كى دہائى دیتےہیں، اور ہر حال میں ان سے مدد طلب كرتےہیں۔ (الجزائرى: ۴؍۴۹۸)\nكفار قریش كى حالت آج كےبعض جاہل مسلمانوں سے كیوں بہتر تھى؟\nقَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۢ\nیہاں دو معنوں كا احتمال ہے: ایك یہ كہ (اور یہ معنی زیاده بہتر ہے) اسكے كہنے كا مقصد یہ تھا كہ جو كچھ مجھے ملا ہے وه میرى دانائى كا نتیجہ ہے۔ دوسرا یہ كہ الله تعالىٰ جانتا تھا كہ میں ہى اسكا مستحق ہوں۔ (ابن جزى: ۲؍۲۷۱)\nآیت میں بیان كیا گیا ہے كہ مالدار آدمى اپنے آپ سے دھوكے كا شكار ہے ، اسكى وضاحت كیجئے.\nثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۢ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٤٩\nیعنى یہ نعمت مجھے اس بنیاد پر دى گئى ہے كہ الله تعالىٰ جانتا تھا كہ میں اس كا اہل ہوں، مقاتل كا قول ہے كہ مجھے یہ نعمت میرےپاس جو بھلائی ہے جسے الله بخوبی جانتا ہے اس کے عوض میں ملی ہے۔ (بل هي فتنة) یعنى یہ نعمت الله كى جانب سے بطور ڈھیل اور بطور امتحان ہے۔(البغوى: ۴؍۲۱)\nكیا ہر روزى اور ہر نعمت انسان كیلئے بھلى مانى جائے گى؟ آیت كى روشنى میں اسے واضح كیجئے.\nبَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٤٩\n(ولكن أكثرهم لا يعلمون) لیكن اكثر لوگ اسے نہیں جانتے ہیں، اسى لئے تو آزمائش كو نوازش سمجھتے ہیں، اور خالص احسان وبھلائى جو خیر كا سبب بھى ہوسكتی ہے، اور باعث شر بھى ان پر خلط ملط ہوجاتی ہے۔ (السعدى: ۷۲۷)\nغافل اور جاہل پر الله كى نعمت کی سنگینی و خطرناکی واضح کیجئے؟\nأَوَ لَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٥٢\nیعنى روزى كى فراوانى اور اسكى تنگى الله كى حكمت ورحمت پر منحصر ہے، وه اپنے بندوں كے احوال سے بخوبی واقف ہے، بسا اوقات الله تعالىٰ روزى تنگ كر كے بندوں پر مہربانى كرتا ہے كیونكہ اگر فراوانى كردیتا تو وه زمین میں بغاوت شروع كردیتے، چنانچہ الله نے اس سلسلے میں انكے دین كى رعایت كى ہے جو كہ فلاح وسعادت كى بنیاد ہے۔(السعدى: ۷۲۷)\nبتائیے كہ روزى كى تنگى بندوں پر الله كى رحمت وشفقت كا باعث كیسے ہے؟\n۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٥٣\nوعید كى آیتیں اپنے سابقہ پیرائے میں كچھ اس تفصیل سے بیان كى گئى ہیں كہ سننے والا مرعوب ہوجائے اور خوف و دہشت میں مبتلاہوجائے حالانکہ وہ کبھی کبھاران وعیدوں کی پرواہ نہ کرنے کا مظاہرہ کرتا ہے لیکن بسا اوقات اس پران کا اتنا گہرا اثرپڑتا ہے کہ وعید سے نجات کی کوشش ہی چھوڑدیتا ہے اور مایوس ہوجاتا ہے۔ لہٰذا الله نے وعید والى آیتوں كے بعد دلوں میں امید كى جوت جگانے والى آیتیں بھی ذكر کردی تاكہ آدمى ساحل نجات كى كوشش میں لگارہے، جیسا كہ قرآن پاك کا اپنا اسلوب ہے كہ یہ ترغیب وترہیب كے حسین امتزاج سے دلوں كا مداوا كرتا ہے۔ (ابن عاشور: ۲۴؍۳۹)\nاس آیت كى سابقہ آیات سے كیا مناسبت ہے؟\nwords\nوَحَاقَاور هر طرف سے گھير ليا.\nخَوَّلنَاهُهم نے ان كو عطاء كيا.\nوَأَنِيبُواتوبه و طاعت كے ساتھ رجوع إلي الله كيا.\nفَرَّطتُجو ميں نے ضائع كيا.\nجَنبِ اللهِالله تعاليٖ كي اطاعت اور اس كے حق ميں."],[465,"§الزمر\ndeeds\nالله تعالىٰ كى تعریف بیان كیجئے اور اسكى نعمتوں (جن میں سب سے عظیم نعمت اسلام ہے) پر اسكا شكر بجالائیے.\nشكر نیك اعمال پر فخر وغرور كے زوال كا سبب ہے، لہذا نیك كام كى توفیق پر آج بکثرت اللہ کا شكر ادا کیجئے.\nایك چھوٹا سا پیغام لكھ كر الله كى عظمت كے نشانات بیان كیجئے.\nguid\nتكبر كے مرض سے بچئے ، کیونکہ قیامت كےدن كبر والے بہت ذلیل ہوں گے.\nتقوىٰ کو لازم پكڑئیے ، كیونكہ یہ راه نجات ہے.\nشرك كے اسباب میں سے ایك سبب جہالت ہے، لہذا خود كى تعلیم پر خاص توجہ دیجئے اور بقدر امكان علم شرعى كے زیور سے آراستہ ہوجائیے.\nrefl\nأَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ ٥٧ أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ ٥٨\nدل میں گردش كرنےوالے احساسات اور دل کی باتوں کو اسی فطرى ترتیب سے بیان كیا گیا جس طرح اسکے دل میں وہاں باتیں کھٹکیں گی اسكے نفس نے جس پستی تک اسے پہنچایا ہے سب سے پہلے اس پر حسرت وافسوس کرے گا، پھر نجات کی امید میں عذر پیش کرے گا، پھر دنیا میں لوٹنے اور نیك كام كرنے كى تمنا کرے گا، جیسا كہ الله تعالىٰ كا قول ہے: ﴿قَالَ رَبِّ ٱرۡجِعُونِ * لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُ﴾ [المومنون: ۹۹- ۱۰۰] كہتا ہے كہ اے میرے رب! مجھے واپس لوٹا دے، كہ اپنى چھوڑى ہوئى دنیا میں جاكر نیك كام كرلوں۔ چنانچہ نظم کلام میں یہ ترتیب سب سے محكم ترتیب مانى جاتی ہے۔ (ابن عاشور: ۲۴؍۵۱)\nقیامت كے دن دل کی بات بیان كرنے میں آیات كریمہ كا حسین تناسب واضح كیجئے.\nوَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ ٦٠\nانہیں متكبرین كى صفت سے متصف كرنے میں یہ اشاره ہے كہ ان كا چہره كالا كركے انہیں سزا دینا انكے گھمنڈ كے عین موافق ہے، اسلئے كہ جب گھمنڈى كا چہره سیاه كیا جاتا ہے تو اس كا غرور ٹوٹتا ہے ، كیونكہ گھمنڈ اسى كے بقدر گھٹتا ہے جس قدر مغرور كو احساس ہو كہ لوگ اسكے عیوب ونقائص سےآگاه ہوچكےہیں ۔ (ابن عاشور: ۲۴؍۵۱)\nقیامت كے دن تكبر كرنے والوں كے چہرے سیاه كرنے كى كیا حكمت ہے؟\nوَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ ٦١\n(وينجي الله الذين اتقوا) یعنى الله تعالىٰ پرہیزگاروں كو جہنم سے نجات دےدے گا، كیونكہ یہ گھمنڈ نہیں كررہےتھے۔ اس سے معلوم ہوا كہ تقوىٰ گھمنڈ كے منافى ہے، كیونكہ تقوىٰ ایك ایسا كامل وشرعى اخلاق ہے جو كہ ظاہر وباطن ہر لحاظ سے منہیات سے بچنے اور مامورات بجا لانے كا تقاضہ كرتاہے، جبكہ كبر دل كى ایك گھاتک باطنى بیمارى ہے۔ (ابن عاشور: ۲۴؍۵۲)\nمتكبرین كے ذكر كے بعد متقین كے ذكر كا كیا فائده ہے؟\nٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ\nیہ اور اس جیسى عبارتیں جو كہ قرآن میں بہت سارے مقامات پرہیں ، اس بات پر دلالت كرتى ہیں كہ الله كےعلاوه تمام چیزیں اللہ کی مخلوق ہیں، اس میں ان سبھی لوگوں كى تردید ہے جو بعض مخلوق كو قدیم (ہمیشہ سے) مانتےہیں، جیسے فلاسفہ ہیں، جن كا كہنا ہے كہ آسمان وزمین پہلے سےہیں، قدیم ہیں، اسى طرح وه لوگ جو روح كو قدیم مانتےہیں ، اور وہ سبھی اہل باطل ہیں جو بہت سى بہكى ہوئى باتیں کہتے ہیں اور الله تعالىٰ كو تخلیق كى صفت سے عارى قرار دیتےہیں۔ (السعدى: ۷۲۸)\nاگر كوئى بعض مخلوق كو قدیم مانتا ہے تو آپ اسكى تردید كیسے كریں گے؟ نیز اس كى بات كےباطل ہونے كى كیا وجہ ہے؟\nقُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ ٦٤\nیعنى یہ حكم تمہارى جہالت سے صادر ہوا ہے، ورنہ اگر تم یہ جانتے كہ جب الله ہر اعتبار سے كامل ہے، وہی تمام طرح کی نعمتوں سے نوازتاہے، تو وہى عبادت كا بھى تنہا مستحق ہے، جبكہ جو ہر زاویے سے ادھورےہیں، نہ نفع دےسكتے اورنہ نقصان تو تم ان كى عبادت كا حكم مجھے کس بنیاد پر دیتے ہو ؟ (السعدی ۷۲۹)\nمشركین كو جہالت سے متصف كرنے كى كیا وجہ ہے؟\nبَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ ٦٦\n(وكن من الشاكرين) الله تعالىٰ كى توفیق وہدایت پر اس كا شكر كرنے والے بن جائیے، چنانچہ جس طرح دنیاوى نعمتوں جیسے صحت، بدن كى عافیت، روزى وغیره كے حصول پر الله كا شكر ادا كیا جاتاہے، اسى طرح دینى واخروى نعمتوں پر بھى اسكى تعریف بیان کی جائے گی اور شكر ادا كیا جائے گا، بلکہدرحقیقت دینى نعمتیں ہى اصل ہیں۔ (السعدى: ۷۲۹)\nالله تعالىٰ نے آیت كریمہ كا خاتمہ (وكن من الشاكرين)سے كیوں كیا ہے؟ وجہ بتائیے.\nبَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ ٦٦\nدینى نعمتیں الله كى جانب سے ہیں، ان میں غور و فکر کرنےاوران پر الله كا شكر بجا لانے سے آدمى عجب وغرور كى آفت سے محفوظ رہتا ہے جس میں كہ اپنى جہالت كیوجہ سے اكثر نیك كام كرنے والے پڑجاتےہیں، ورنہ اگر آدمى حقیقت حال سے آگاه ہوتو نعمت پر غرور كا شكار کبھی نہیں ہوگا، بلكہ اس پر زیاده سے زیاده الله كا شكر بجا لائے گا۔(السعدى: ۷۲۹)\nآیت کریمہ میں غرور اور خود پسندى كے ازالے كى طرف رہنمائى كى گئى ہے جس میں نیك كام كرنے والے پڑجاتےہیں ، اس کی توجیہ بیان کیجئے.\nwords\nكَرَّةًلوٹنا.\nبِمَفَازَتِهِماپني كاميابي ؛ اپنے مقصود كا حصول.\nمَقَالِيدُخزانے كي چابياں.\nلَيَحبَطَنَّوه اسے باطل كريں گے.\nقَبضَتُهُميں نے اسے اپنے هاتھ ميں پكڑا.\nمَطوِيَّاتٌلپيٹے هوئے(هاتھ ميں )."],[466,"§الزمر\ndeeds\nآج نماز میں الله كے روبرو بہتر سے بہتر انداز میں قیام كیجئے، تاكہ آخرت میں اسكے حضور كھڑا ہونا آپ كیلئے آسان ہوجائے.\nآج ہى كوئى ایسا كام انجام دیجئے جو آپ كى ذات سے تكبر كے ازالے میں معاون ہو، جیسے فقراء اور مزدوروں كے ساتھ بیٹھنا ، انكے ساتھ كھانا یا انہیں اپنے گھر مدعو كرنا.\nآج آپ ایك سے زائد قسم كى عبادتیں انجام دیجئے جیسے نماز پڑھنا، روزه ركھنا اور صدقہ كرنا، شاید جنت كے ان دروازوں سے آپ كو داخلے كا موقع مل جائے جو ان اعمال كیلئے مخصوص ہیں.\nguid\nبندے نےجو بھى كام كئےہیں، قیامت كے دن ان كا پورا پورا بدلہ دیا جائےگا.\nجوشخص آپ كو بھلائى كى دعوت دے تو اس سےاعراض مت كیجئے بلكہ اسكى دعوت پر لبیك كہئے.\nظاہر وباطن دونوں میں پاكیزگى اختیار كرلیجئے، پاك چیزیں كھا ئیے، پاكیزه لباس زیب تن كیجئے، تاکہ بروز قیامت آپ سے بھى كہاجائے.\nrefl\nوَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا\nاس سے معلوم ہو رہا ہے كہ موجوده نور قیامت كے دن ماند پڑ جائےگا ، ختم ہوجائےگا اور كائنات تاریكى میں كھوئى جائے گى، كیونكہ الله نے فرمایا ہے كہ سورج لپیٹ دیا جائےگا، چاند بےنور ہوجائے گا، ستارے جھڑ جائیں گے اور لوگ تاریكى میں ڈوبے ہوں گے كہ اچانك زمین اپنے رب كے نور سے جگمگا اٹھے گى،ایسا اس گھڑى ہوگا جب الله تجلى فرمائےگا اور بندوں كے بیچ فیصلے كیلئے نازل ہوگا ، اس روز الله تعالىٰ اپنے مومن بندوں كو قوت دے گا اور انہیں جدید وجود و نشأت بخشے گا تاكہ الله كا نور انہیں نا جلائےاور وه الله كا دیدار كرسكیں ، ورنہ الله كا نور تو اتنا عظیم ہے كہ اگر الله اسے كھول دے تو اسكے چہرے كا نور تا حد نگاه مخلوقات كو جلا كر راكھ كردے۔ (السعدى: ۷۳۰)\nاس كى كیا دلیل ہے کہ ابتداء میں لوگوں كو تاریكى میں اٹھایا جائےگا؟ نیز آیت كریمہ اور اس حدیث میں تطبیق كى كیا صورت ہوگى جس میں ہے كہ الله كا نور تاحد نگاه مخلوقات كو جلا دیتاہے؟\nوَجِاْيٓءَ بِٱلنَّبِيِّۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ ٦٩\nانبیاء کرام كو لایا جائےگا پھر الله سوال كرےگا كہ ان كى امتوں نے انہیں كیا جواب دیا تھا، اسى طرح الله كى راه میں شہید ہونے والوں كو بھى حاضر کیا جائےگا اور وه گواہى دیں گے كہ انہوں نے کس کی خاطر الله كے دین كا دفاع كیا تھا۔ (القرطبى: ۱۸؍۳۲۵)\nقیامت كے مشكل دن انبیاء وشہداء كو كیوں لایا جائےگا؟\nوَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا\nخبر كى ابتداء مستحقین عذاب كےذكر سے كى گئى ہے، کیوں كہ وہی یہاں سب سے اہم ہے، اس لئے کہ نصیحت سے اعراض کرنے والوں کے لئے یہ وعظ ونصیحت اور انذار و ترہیب كا مقام ہے جنہوں نے قرآن میں وارد اس جیسى نصیحتوں سى عبرت نہیں پکڑی، رہے اہل ثواب اور نیك لوگ تو ان سے مقصود حاصل ہوچكا ، اب ان كے بارے میں جو كچھ ذكر كیا جائےگا وه بشارت اور مدح وثناء كى تكرار ہی ہوگى۔(ابن عاشور: ۲۴؍۶۹)\nآیت كریمہ میں مستحقین عذاب كےذكر سے ابتداء كا فائده كیا ہے؟\nوَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا\nكافروں كے كفر كےدرجات مختلف ہونے كى وجہ سےانہیں مختلف گروہوں میں رکھا گیا ہے، اگر یہاں كافروں سے مراد مشركین مكہ ہیں جو اس وعید سے مقصود (اول) بھى ہیں تو ان کے کفر پر سختی سے جمے اور ڈٹے رہنے اور مسلمانوں سے عطف ونرمى اور سختى وشدت میں الگ الگ ہونے کی وجہ سے ان کے مختلف گروہ ہوں گے۔(ابن عاشور : ۲۴؍۶۹)\nكافروں كو جہنم كى طرف ہنكا كر لےجاتے وقت ان کے مختلف گروہ کیوں ہوں گے؟\nوَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ\nاہل جنت کے گروہ ان کے درجات اور تقویٰ كے مراتب كےاعتبار سے تشکیل پائیں گے۔ (ابن عاشور: ۲۴؍۷۱)\nجنت میں داخلے كے وقت متقیوں کے مختلف گروہ کیوں بنائے جائیں گے ؟\nوَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ\nد ونوں جماعتوں (اہل جنت اور اہل دوزخ) كیلئے بھلے ایك ہى لفظ (وسيق) استعمال كیا گیا ہے لیکن اہل جہنم كو لےجانے كا مطلب ہے: انہیں ذلت ورسوائى كے ساتھ جہنم کی طرف ہانكتےہوئے لےجانا ، جیسے حاكم پر خروج كرنے والوں اور قیدیوں كو جیل یا قتل كیلئے لے جایا جاتاہے۔ جبكہ جنتیوں كو لے جانے سے مراد ان كى سواریوں كو تزك واحتشام اور پورے اعزاز كےساتھ لےجانا ہے ، كیونكہ جنتیوں كو سوارى پر سوار كركے لے جایا جائےگا، جیسے كہ بادشاه كےپاس آنے والوں كى تكریم ہوتى ہےاور انہیں شرف بخشاجاتا ہے۔ لہٰذا دونوں كے لے جانے میں بہت فرق ہے۔(القرطبى: ۴؍۱۴۲)\nاہل جہنم اور اہل جنت كو ان كے ٹھكانوں تك لےجانے میں كیا فرق ہے؟\nحَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ ٧٣\nیہاں (حتى إذا جاءوها)كا جواب شرط مقدر ہے، اور جنتیوں كیلئے جنت كے دروازے كھولنا ان كى تعظیم وتكریم كے طور پر ہوگا۔ فرشتےاور جنت كے نگہبان سلام كرتے، بشارت دیتے اور تعریف كرتےہوئے ان سے ملیں گے، جبكہ ان کے مقابلے میں كافروں سے الله كےسخت ترین فرشتےانہیں ڈانٹتے پھٹكارتےہوئے ان كا سامنا كریں گے۔ چنانچہ تقدیرى عبارت كےاعتبار سے مطلب یہ ہوگا كہ جب یہ حال ہوگا تو اہل جنت بامراد وشاد كام ہوجائیں گے، جنت میں ملى نعمتوں سے خوش وخرم ہوں گے۔ یہاں جواب شرط محذوف ہونے كى وجہ سے ذہن امید ورجاء كى ہر صورت اور ہر بلندى تك جاتاہے۔ (ابن كثیر: ۴؍۶۸)\nاس آیت میں جواب شرط كےحذف كا كیا فائده ہے؟\nwords\nوَنُفِخَپھونكا گيا(پهلا نفخه جس سے مخلوق مر جائے گي).\nفَصَعِقَپس وه مر گيا.\nزُمَرًاجماعتيں.\nفَبِئسَپس وه قبيح هوا.\nطِبتُمتو گناهوں كي گندگي سے پاك هوئے.\nنَتَبَوَّأُهم نازل هوتے هيں."],[467,"§الزمر ، غافر\ndeeds\nیہ دعاء پڑھئے: (اَللّٰهُمَّ أَحْسِنْ عَاقِبَتِىْ فِى الْأُمُورِ كُلِّهَا، وَأَجِرْنِىْ مِنْ خِزْیِ الدُّنْيَا، وَعَذَابِ الْآخِرَةِ) ‘‘اے اللہ! میرے تمام افعال و اعمال کے انجام کو اچھا کردے اور مجھے دنیا کی ذلت و رسوائی، مصیبت و پریشانی اور آخرت کے عذاب سے حفاظت فرما.\nجب آپ یہ آیت پڑھئے: (غَافِرِ الذَّنْۢبِ وَ قَابِلِ التَّوْبِ) (گناه بخشنے والا اور توبہ قبول كرنے والا) تو كہئے: اے گناه بخشنے والے میرے گناه معاف فرمادے، اور اے توبہ قبول كرنے والے میری توبہ قبول کرلے.\nكوئى ایسى كتاب پڑھئے جس سے فر شتوں اور انكے وظائف واعمال سے متعلق آگاہى ہو.\nguid\nالله تعالىٰ كى عظمت بیان كیجئے جیسا كہ الله كےان اسماء سے نمایاں ہے.\nاعدائے اسلام كو دنیا كى جو فراوانى حاصل ہے، اس سے دھوكہ مت كھائیے.\nباطل جھوٹی اور کھوٹی دلیلوں سے مت الجھئے، اور ہمیشہ حق تک پہنچنے کا ارادہ فرمائیے.\nrefl\nوَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٧٥\n(قِيْلَ)کا فاعل محذوف ہے کیونکہ فاعل متعین نہیں ہے، بلکہ ہر ایک مخلوق اللہ تعالیٰ کے فیصلہ و حکم پر اللہ کی تعریف و ثنا بیان کرےگی، آسمان و زمین والے، نیکوکار و بدکار لوگ اور انسان و جنات سب اللہ کی حمد بیان کریں گے یہاں تک کہ جہنمی بھی اس فیصلہ پر اللہ کی تعریف ہی کریں گے گویا پوری کائنات کی زبان پر الْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِيْنَ کا کلمہ جاری ہوگا (ابن القیم: ۲: ۴.۳)\nآیت كریمہ میں فعل(قِيْلَ) صیغۂ مجہول کے ساتھ کیوں آیا ہے؟\nوَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ٧٥\nپورى كائنات خواه ناطق ہو یا غیر ناطق الله رب العالمین كى حكمت اور اسكےعدل پر ثناخواں ہوگى۔ یہاں قول كى نسبت كسى ایك كى طرف نہ كرتےہوئے مطلق ركھا گیا ہے تاكہ دلالت اس بات پر ہو كہ سارى مخلوق كى زبان پر الله كى حمد كے ترانے ہوں گے۔(ابن كثیر: ۴؍۷۰)\nآیت كریمہ میں (قَالُوْا) كہنے كے بجائے (قِيْلَ) كیوں كہاگیا ہے؟\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ٢\nیہاں الله كى صفت (العزيز) اور (العليم)سے اس بات كى جانب اشاره ہے كہ قرآن كو جھٹلانے والے اور اسے من جانب اللہ نہ ماننے والے مغلوب ومقہور ہوں گے۔ اور یہ کہ الله ان چیزوں كو اچھى طرح جانتا ہے جو ان كے نفوس چھپاتےہیں پھر اس پر ان كا محاسبہ بھى كرےگا۔ اور اشاره اس بات كى طرف بھى ہے كہ قرآن غالب اور خوب جاننے والے كا كلام ہے۔ لہٰذا غیر الله كو نہ اس جیسے كلام پر قدرت ہے اور نہ ہى اس جیسا كلام پیش كرنے كا كوئى علم ہے۔ (ابن عاشور: ۲۴؍۷۹)\n(العزيز) اور (العليم) كى صفت سے آیت كریمہ كےاختتام كى كیا حکمت ہے؟\nغَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ\nیہ الله كے اس قول جیسا ہے: ﴿نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ * وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ﴾ [الحجر: ۴۹- ۵۰] میرے بندوں كو بتادو كہ میں بہت ہى زیاده بخشنے والا اور بڑاہى مہربان ہوں۔ اور ساتھ ہى میرا عذاب بھى نہایت ہى دردناك ہے۔ یہ دونوں صفتیں قرآن میں متعدد مقامات پر ایك ساتھ آئى ہیں تاكہ بنده امید وبیم كى حالت میں باقى رہے۔ (ابن كثیر: ۴؍۷۱)\nالله تعالىٰ نے بخشش و مغفرت اور سزا و عقاب کی صفت كو یہاں اور دیگر مقامات پر ایك ساتھ كیوں ذكر كیا ہے؟\nغَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ\nتوبہ كرنے والے گنہگار كیلئے الله نے دو رحمتیں یكجا كردى ہے، یا الله تعالىٰ اسكى توبہ قبول فرمائے گا اور اسے نیكى شمار كرے گا یا پھر اس سے كوئى ایسا گناه مٹا دےگا جس سے اس نے توبہ كرلی ہے اور اس پر نادم ہوا ہے۔ چنانچہ الله كى رحمت اور اسكے فضل سے وه ایسے ہوجائےگا كہ جیسے اس نے گناه كیا ہى نہیں۔ (ابن عاشور: ۲۴؍۸۰)\nالله تعالىٰ نے (غافر الذنب) پر (قابل التوب) كا عطف كیوں كیا ہے؟\nمَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ ٤\nالله تعالىٰ اپنے اس قول (فلا يغررك تقلبهم في البلاد) میں فرمارہاہے كہ اے محمد ! كفار كا کفر کے باوجودشہروں میں چلنا پھرنا ، انكا مختلف شہروں میں ٹھہرنا اور وہاں قیام كرنا آپ كو دھوكے میں نہ ڈال دے اور آپ یہ گمان كرنے لگیں كہ انہیں مہلت دی گئی ہے اور وہ ادھر ادھر گھوم پھر رہےہیں اور ان كے كفر پر انكى گرفت جلد از جلد نہیں ہورہى ہے، اور وہ عذاب الٰہى كی لپیٹ میں نہیں آرہےہیں کیونکہ ان كےپاس بھى کچھ حق ہے۔ (آپ اس دھوكے میں مت رہئے) ہم نے اس لئےانہیں ہرگز مہلت نہیں دى ہے، بلكہ اس لئے دی ہے کہ كتاب میں لكھى مدت پورى كرنى ہے تاكہ ان پر تیرے رب کےعذاب كا حکم ثابت ہوجائے۔ (الطبرى : ۲۱؍۳۵۲)\nالله تعالىٰ كافروں كو كفر پر اصرار كےباوجود مہلت كیوں دے رہاہے اور اپنی نعمتوں سے انہیں کیوں نوازتا ہے؟\nٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ\nاگر یہ كہاجائےكہ (ويؤمنون به) كا فائده كیا ہے؟ جبكہ معلوم ہے كہ عرش كو اٹھانے والے اور اسكے آس پاس كے فرشتے الله پر ا یمان ركھتےہیں، تو جواب یہ ہوگا كہ اس سے ایمان كى فضیلت اور شرف وعظمت كا اظہار مقصود ہے۔ (ابن جزى: ۲؍۲۷۶)\nالله كے اس قول (ويؤمنون به) كے ذكر كا كیا فائده ہے؟ جبكہ یہ معلوم ہے كہ الله كا عرش اٹھانے والے فرشتے مومن ہى ہیں؟\nwords\nحَآفِّينَگھيرے هوئے.\nوَقُضِيَ بَينَهُم بِالحَقّمخلوق كے مابين عدل سے فيصله هوا.\nذِي الطَّولِمويشيوں اور ديگر انعامات والا.\nفَلاَ يَغرُركَپس وه تمهيں نه دھوكا دے.\nلِيُدحِضُواتاكه اسے باطل كرديں.\nوَقِهِماور ان كو بچالے."],[468,"§غافر\ndeeds\nآپ اپنے بھائیوں اور دیگر اہل خانہ كو نماز كا حكم دیجئے ، اس امید پر تاكہ وه جنت میں آپ كے ساتھ ہوں.\nفرشتوں کی اقتدا کرتے ہوئےدیگر مومنوں كے حق میں بھى آپ ویسے ہى دعاء كیجئے جیسے اپنے لئے كرتےہیں.\nاپنے بعض عیوب اور گناہوں كى نشاندہى کے بعد الله سے توبہ و استغفار كیجئے، قبل اس كے كہ آخرت میں آپ انكا اعتراف كریں جو بےفائده ہوگا.\nguid\nسعید بن جبیر نے كہا كہ مومن جب جنت میں داخل ہوگا تو اپنے باپ، بیٹے اور بھائى كےبارےمیں پوچھے گا كہ وه كہاں ہیں؟ اسے بتایا جائےگا كہ وه عمل میں تمہارے درجے تك نہیں پہنچے تھے۔ اس پر وه كہےگا كہ میں نے تو اپنے لئے اور ان كى خاطر بھى عمل كئےتھے، پھران سب کو ان کے ہی درجے میں رکھا جائے گا اور سب اكٹھا ہوجائیں گے۔ اس کے بعد سعید بن جبیر نے یہ آیت كریمہ پڑھى.\nجان لیں كہ سب سے بڑی رحمت جو بنده کوحاصل ہوگی وه یہ ہے كہ الله اسے گناہوں كے عواقب و انجام سے بچا لے.\nاگر الله كو راضى كرنے والا كوئى كام آپ انجام دے رہے ہیں اور كفار اس پر آگ پا ہورہےہیں تو ان كى ناراضگى كى پرواه مت كیجئے.\nrefl\nرَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٨\nاس آیت میں یہ معنی داخل ہے كہ ایک ساتھ رہنے والےمیاں بیوى اولاد اور ساتھى میں سے جس كو الله ملا ئےگا وه اپنے قریبى ساتھی سے مل كر مگن ہوجائے گا اور اس كا اپنے ساتھی کے ساتھ رہنا باعث خیر و سعادت ہوگا جو اس كے خود كے عمل اور اسباب ِ عمل سے باہر کی ایک نعمت ہوگی۔ جیسا كہ فرشتے مومنین اور ان کے صالح باپ دادوں، بیویوں اور اولادكےحق میں بھى دعائیں مانگتےہیں۔ (السعدى: ۷۳۳)\nآیت كریمہ میں نیك لوگوں كى صحبت پر ابھارا گیا ہے ، اسكى وضاحت كیجئے.\nرَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ\nیعنى اِنہیں اور اُنہیں جنت میں آزو بازو اور ایک دوسرے کے قریب جمع فرمادے ، تاكہ اس کی وجہ سے ا نكى آنكھیں ٹھنڈى ہوں ۔ (ابن كثیر: ۴؍۷۴)\nالله نے آباء واجداد ، میاں بیوى اور ذریت كا ہى ذكر كیوں فرمایا؟\nإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٨\n(العزيز) یعنى ہر چیز پر غالب ہے۔ تیرے غلبے وعزت كےسبب ہى بندوں كےگناه مٹتےہیں، ركاوٹیں اور مصیبتیں دور ہوتى ہیں، اور ہر بھلائى تك ان كى رسائى ہوتى ہے... (الحكيم) جو اشیاء كو ان كے مناسب مقام پر ركھتاہے، لہذا اے ہمارے رب! ہم تجھ سے كسى ایسى چیز كا سوال نہیں كرتے جو تیرى حكمت كے خلاف ہو۔ بلكہ مومنین کو بخش دینا تیرے فضل وكرم كا تقاضہ اور تیری حکمت کا حصہ ہے جس کی خبر تو اپنے رسولوں کے ذریعہ دی ہے۔ (السعدى : ۷۳۲)\nفرشتوں کی دعاؤں كا اختتام ان دونوں صفات (العزیز الحكیم) سے كرنے كى كیا وجہ ہے؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ ١٠\n(مقت) وه شدید ناراضگى جو گناه یا كسى عیب كے باعث ہوگی اور كفار كى یہ حالت ان كے جہنم میں داخلے كے وقت ہوگى، كیونكہ جب وه جہنم میں جائیں گے تو ایك دوسرے پر سخت ناراض ہوں گے ، اوراس معنیٰ كا بھى احتمال ہے كہ ہر شخص خود اپنى ہى ذات سے خفا ونالاں ہو گااسى وقت فرشتے ان سے كہیں گے كہ دنیا میں تمہارے كفر پر الله اس سے كہیں زیاده ناراض ہوتا تھا جتنا آج تم اپنے آپ پر ہورہےہو۔ (ابن جزى: ۲؍۲۷۷)\nجہنم میں كفار خود اپنے آپ پر كیسے ناراض ہوں گے؟\nقَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ ١١\n(أمتنا اثنتين وأحييتنا اثنتين)یہ ان كى جانب سے دوباره زنده كئےجانے كا لامحالہ اقرار ہے۔ اس لالچ میں كہ شاید وه اس ناراضگی سے بچ نكلیں جس نے الله كو شدید خفا كیا ہے کیوں كہ جب انہیں اسلام كى طرف بلایا جاتاتھا تو وه صاف انكار كرتے تھے۔ اگر یہ كہاجائے كہ ان كا یہ قول (أمتنا اثنتين وأحييتنا اثنتين) ان كے اعتراف گناه كا سبب كیسے ہوگیا؟ تو جو اب یہ ہے كہ وه بعث بعد الموت (دوباره اٹھائے جانے)كا انكار كرتےتھے لیکن جب دیكھیں گے كہ ایك بار پھر انہیں مارا اور جلایا گیا ہے تو یقین كرلیں گے كہ الله اس پر قادر ہے، لہٰذا وہ اپنے گناہوں كا اقرار بھى كرلیں گے، ان کا اصل گناه انكار بعث تھا ، نیز اسكے نتیجے میں اللہ کی معصیت ونافرمانى جیسے بہت سی گناہیں، كیونكہ جو آخرت پر ایمان نہیں ركھتا ہے وه معصیت كى كچھ پرواه نہیں كرتا ہے۔ (ابن جزى: ۲؍۲۷۸)\nفاسد اعتقاد معصیت كے ارتكاب كا سبب ہے ، آیت كى روشنى میں اسے واضح كیجئے.\nيُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ\n(يلقي الروح) (روح ڈالتا ہے) یعنى وحى اتارتا ہے، وحى كو روح اس لئے كہا گیا ہے كیونكہ اس سے دلوں كو زندگى ملتى ہے۔ (البغوى: ۴؍۳۸)\nوحى كو روح كیوں كہاگیا ہے؟\nيُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ ١٥\n(يوم التلاق) ملاقات كا دن ، یعنى روز قیامت ، اسے ملاقات كا دن اس لئے كہاگیا ہے كیونكہ لوگ ایك دوسرے سےاس دن ملیں گے۔اس کی توجیہ میں یہ بھى كہاگیا ہےكہ وہاں آسمان اور زمین والے ملاقات كریں گے۔اور اس بابت ایك قول یہ بھى ہے كہ سارى مخلوق وہاں اپنے رب سے ملےگى۔ (ابن جزى: ۲؍۲۷۸)\nملاقات والا دن (يوم التلاق) كیا ہے اور اس كا یہ نام كیوں ركھا گیا؟\nwords\nلَمَقتُ اللهِيقيناً الله تعاليٰ كا بهت سخت غصه.\nيُنِيبُوه الله تعاليٰ كي اطاعت كي طرف رجوع كرتا هے.\nيَومَ التَّلاَقِملاقات كا دن / جب اگلوں اور پچھلوں ميں ملاقات هوگي.\nبَارِزُونَظاهرهونے والے (اپنے رب كے سامنے )."],[469,"§غافر\ndeeds\nكسى ایسے شخص كو یاد كیجئے جس پر آپ نے كبھى زیادتى كى ہو، اس سے معافى تلافى كیجئے ،یا غائبانہ طور پر اس كے حق میں دعاء كیجئے نیز اپنے گناہوں پر الله سے استغفار كیجئے.\nآج اپنے دل كى طہارت كا پورا اہتمام كیجئے اور اس پر نظر ہى مت ڈالئے جو آپ كے لئے حلال نہیں ہے، خواه سڑك وبازار میں ہو، یا موبائل ، لیپ ٹاپ اور ٹیلى ویزن وغیره میں.\nان لمحات كو یاد كیجئے جنہیں آپ نے غفلت وگناه میں گزار دیا ، اتنا وقت قرآنى آیات میں غور وخوض پر صرف كیجئے ، شاید یہ نیكیاں برائیوں کو مٹادیں.\nguid\nقیامت كےدن كسى پر بھى كوئى زیادتى نہیں ہوگى ، ایسا نہیں ہوگا كہ كسى كى بدى میں اضافہ كردیا جائے یا كسى كى نیکی كم كردى جائے.\nقیامت كى ہولناكى انتہائى شدید ہوگى یہاں تك كہ مارے گھبراہٹ كے دل حلقوم تك پہونچ جائیں گے.\nلوگ سابقہ اقوام كے آثارونقوش تسلى اور وقت گزاری كیلئے دیکھتے ہیں اور معذب اقوام كى سزاؤں میں غور كے اس پہلو سے بچتےہیں جس كا الله نے حكم دیا ہے.\nrefl\nإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ١٧\nكیونكہ الله ہر شى كا علم ركھتاہے، كوئى بھى چیز اسكے علم سے باہر نہیں ہے، اس لئے كسى كا بدلہ اس لئے موخر نہیں ہوگا كہ وه كسى اور میں مشغول ہوگیا، جس طرح وه بیك وقت سب كو روزى دیتاہے اسى طرح ایك ہى لمحے میں سب كے محاسبے پر بھى قادر ہے۔ (القرطبى: ۱۸؍۳۴۱)\nالله تعالىٰ اپنے بندوں كا انتہائى تیزى سے حساب كتاب كرےگا، اس بارے میں رب كى عظمت بیان كیجئے.\nوَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ\nقیامت كو (الأزفة)كہاگیا ہے كیونكہ قیامت قریب ہے، اور ہر آنے والى چیز قریب ہى ہوتى ہے (إذ القلوب لدى الحناجر كاظمين) ایسا اس لئے ہوگا كیونكہ خوف كیوجہ سے دل اپنى جگہ سے ہٹ جائیں گے، اتھل پتھل میں حلقوم تك آجائیں گے نہ یہ اپنى جگہ واپس لوٹیں گے نہ ہى منہ كےراستے باہر نکلیں گے كہ مرجائیں اور راحت نصیب ہوجائے ۔ (البغوى: ۴؍۳۹)\nقیامت كو (الأزفة) كیوں كہاگیا ہے ؟ اور دل کے حلق تك آنے کی کیفیت کیا ہوگی؟\nيَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ ١٩\nالله تعالىٰ خبر دےرہا ہے كہ اس كا علم كامل اور ہر چیزپر محیط ہے ، چاہے وه بڑی ہو یا چھوٹی ، کم ہو یا زیادہ ، موٹى ہو یا باریك ، تاکہ انسان اللہ کے علم کا لحاظ رکھتے ہوئے اس سے خوف کھائے اور كماحقہ اس سے حیاء کرے ، اور تقویٰ اختیار کرے ، اور اس كے مراقبے میں اس یقین کے ساتھ لگا رہے کہ وہ اسے دیکھ رہا ہے۔ (ابن كثیر: ۴؍۷۷)\nاس آیت كے وه عملی فائدےكیا ہیں جن سے ایك مومن مستفید ہوتاہے؟\nيَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ ١٩\nابن عباس رضی اللہ عنہما فرماتے ہیں كہ یہ وه آدمى ہے جو لوگوں كےساتھ بیٹھا ہوتاہے ، وہاں سے كوئى عورت گزرتى ہے تو وہ لوگوں سے نظریں چراکراسے دیكھتا ہے، نیز انہیں سے مروى ہےكہ یہ وه شخص ہے جو كسى عورت كو نہارتا ہے اور جب اس كے ساتھى دیكھ لیتےہیں تو نظریں جھكا لیتاہے پھر جب دیکھتا ہے کہ اس کے احباب غفلت میں ہیں تو پھر چپکے سے اسے دیکھنے لگتا ہے لیکن جب ان کی نظر پڑتی ہے تو پھر وہ اپنی نظریں جھکالیتا ہے۔ اور الله تعالىٰ اسكے بارے میں جانتا ہے كہ وه عورت كى پوشیده چیزیں دیكھنا چاہتاہے۔ ابن عباس رضی اللہ عنہما كہتےہیں كہ (وما تخفي الصدور) كا مطلب یہ ہے كہ الله یہ بھى جانتا ہے كہ اگر اسے خلوت مل جائےتو آیا آدمى عورت كےساتھ زنا كرےگا یا نہیں ۔ (القرطبى: ۱۸؍۳۴۳)\nآنكھوں كى خیانت كیسے ہوتى ہےاور ایسے لوگ دلوں میں کیا چھپاتے ہیں؟\nوَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ٢٣\nالله تعالىٰ نے فرعون كے ساتھ موسیٰ علیہ السلام كا قصہ رسول الله صلی اللہ علیہ وسلم كو اس لئے سنایا تاكہ آپ صلی اللہ علیہ وسلم كو اس سے تسلى حاصل ہو، صبر كا حوصلہ ملے، اور یہ یقین ہوجائے كہ آزمائش خواه كتنى بھى سخت ہو، اسكے بعد آسانى آتى ہے، اور الله تعالىٰ آپ صلی اللہ علیہ وسلم كى قوم والوں كے خلاف آپ كى ضرور مدد فرمائےگا جیسا كہ اس نے فرعون كے مقابلے میں موسیٰ علیہ السلام كى مدد كى تھى۔ (الجزائرى: ۴؍۵۲۷)\nفرعون كے ساتھ موسیٰ علیہ السلام كا قصہ ذكر كیا گیا ہے ، بتائیے كہ ماقبل كى آیتوں سے اسكى كیا مناسبت ہے؟\nإِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ ٢٤ فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ٢٥\nان تینوں (فرعون، ہامان اورقارون) كى اجتماعى رائے تھى كہ بنو اسرائیل ، موسیٰ كےپیروكاروں ، ان میں طاقت والوں اور جوانوں كوقتل كردیا جائے، خدمت اور غلامى كیلئے بس عورتوں كو چھوڑ ا جائے ۔ اور الله تعالىٰ كا یہ قول (وما كيد الكافرين إلا في ضلال) نہایت مختصر ہے جو بتارہا ہے كہ یہ تینوں اللہ کی مشیئت و قدرت سے اپنى پلاننگ میں ناكام رہے ، اور بنو اسرائیل كے كسى بھى شخص كو قتل نہیں كرسكے ، بلكہ الله نے ان كى ہر كوشش وتدبیر فیل كردى ۔ (ابن عطیہ : ۴؍۵۵۴)\nالله كا اراده بادشاہوں كےارادےسے برتر ہے، ان دونوں آیتوں كى روشنى میں اسكى وضاحت كیجئے.\nفَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ٢٥\nاس نكتے پر غور كیجئے جس كا قرآن میں اكثر ذكر آتاہے، كہ اکثر کوئی چیز كسى معین واقعے یا خاص پس منظر میں بیان كى جاتى ہے اور الله تعالىٰ اس كا حكم عام ركھنا چاہتا ہے تو اس حكم کے ساتھ ساتھ عمومی وصف بھی بیان كردیتاہے ، تاكہ حكم عام ہوجائے اور اس میں وه صورت بھى شامل ہوجائے جس كےلئے كلام لایا گیا ہے، اور اس معین چیز سے حكم كى تخصیص كا وہم دور ہوجائے ۔ اسى لئے (وَ مَا كَيْدُ هُمْ اِلَّا فِيْ ضَلٰلٍ)كہنے كے بجائے الله نے (وما كيد الكافرين إلا في ضلال) كہا ہے۔ (السعدى: ۷۳۶)\nآیت كریمہ كا اختتام عام لفظ (وما كيد الكافرين)سے كیوں كیا گیا ؟ \"وما كيد فرعون\" يا \"وما كيدهم\" كیوں نہیں كہاگیا؟\nwords\nيَومَ الآزِفَةِقريب كا دن (مراد يوم قيامت ).\nلَدَى الحَنَاجِرِدل حلق كو پهنچے هوئے ؛ شدت كرب كي وجه سے.\nكَاظِمِينَغم و ملال سے بھرے هوئے.\nخَائِنَةَ الأَعيُنِحرام پر پڑنے والي چور نظر.\nوَاقٍبچانے والا."],[470,"§غافر\ndeeds\nاگر آپ كسى مجرم سے خوفزده ہیں تو یہ دعا پڑھا كریں: “اَللّٰهُمَّ إِنَّا نَعُوْذُ بِكَ مِنْ شُرُوْرِهِمْ وَنَدْرَأُ بِكَ فِىْ نُحُوْرِهِمْ” اے اللہ! ہم تیرے ذریعے ان کی شرارتوں (برائیوں) سے پناہ مانگتے ہیں اور ان کا مقابلہ کرنے کے لئے تجھے ان کے سامنے رکھتے ہیں.\nاگر كسى عالم یا داعى كا بیوقوف لوگ مذاق اڑا رہے ہوں توآل فرعون کے مردمومن کی پیروی کرتے ہوئے كسى میسیج یا مضمون كے ذریعے اس كا دفاع كیجئے.\nفضول خرچى ، جھوٹ اور كبر وغرور سے الله کی پناه طلب كیجئے.\nguid\nمتكلم كا كردار اس كے جھوٹے یا سچے ہونے كى دلیل ہوا كرتاہے.\nمومن ہر خوف كےوقت الله كى طرف پناه لیتاہے.\nہدایت سےمحروم سب سے زیادہ وہ ہوتا ہے جو بہت زیادہ گناہوں کا ارتکاب کرتا ہے اور پھر جھوٹ بولتاہے اور کہتا ہے کہ گناہ کرنے کی اجازت اللہ نے دے رکھی ہے.\nrefl\nوَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ ٢٦\nفرعون كےغرور اورواقعات و معاملات میں قلتِ فكر وتدبرنے اسے ایسے گمان پر آماده كرركھا تھا كہ اپنے دین كےخلاف ہر چیز كو فساد سمجھتا تھا، اس لئے کہ فرعون كےپاس عارضی فائدے اور اپنے دین سے انسیت و محبت کے سوا اپنے دین كى كوئى دلیل وحجت بھى نہیں تھى ۔ (ابن عاشور: ۲۴؍۱۲۵)\nآباء واجداد كےعادات واطوار اگر فاسد ہوں تو یہ ہدایت كى راه كا روڑا بن جاتےہیں ، اس بات كى وضاحت كیجئے.\nوَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ ٢٧\nجو شخص حساب وكتاب كےدن پر سچا ایمان نہ رکھتا ہو وه احسان پر ثواب كا خواہاں نہیں ہوتاہے، اور نہ برائى بدسلوکی، اور بدعملی پر خوف کھاتا ہے۔ (الطبرى: ۲۱؍۳۷۵)\nموسیٰ علیہ السلام نے بطور خاص اس شخص سے اللہ کی پناہ کیوں طلب کی، جو حساب كےدن پر ایمان نہیں ركھتا ہے ؟\nوَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ\nالله نے آل فرعون کے ایك مومن آدمى كى تعریف بیان كى ہے جو اپنا ایمان چھپا ركھا تھا۔ الله نے اپنى كتاب میں اسے بیان كیا، مقدس مصاحف میں اس كلام كا تذكره كیا جسے اس نے كافروں كى ایك مجلس میں كہاتھا۔ اب ذرا اس سے عمر بن خطاب رضی اللہ عنہ كا موازنہ كیجئے جنہوں نے مكے میں تلوار سونت كر على الاعلان كہاتھا “والله لا اعبد الله سرا بعد اليوم” (الله كى قسم! آج كے بعد میں الله كى خفیہ عبادت نہیں كروں گا)۔ (ابن عطیہ: ۴؍۵۵۵)\nیہ آیت فضائل صحابہ پر دلالت كررہى ہے ، اسكى وضاحت كیجئے.\nوَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡ\nیہ کلام ایسا نہیں ہےكہ اس آدمى كو موسیٰ علیہ السلام كى رسالت وصداقت میں كوئى شك تھا، بلكہ یہ حکیمانہ و مشفقانہ اسلوب خطاب ہے جو انہیں اذیت و تکلیف دینے سے ، تنازل اپنانے اور ایذاء رسانى سے باز رکھنے کے لئے استعمال کیا گیا ہے۔ (القرطبى: ۱۸؍۳۴۸- ۳۴۹)\nكیا آل موسیٰ كے مومن آدمى كا یہ قول موسیٰ علیہ السلام كى صداقت پر شك كى بنیاد پر تھا؟ نیز یہ بھى بتائیے كہ اس اسلوب سے ہم كون سا دعوتى اسلوب سیكھ سكتےہیں؟\nوَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡ\nیہاں (كل) نہیں ، اس مومن بندے نے (بعض) كا لفظ استعمال كیا، حالانكہ وه سب عذاب انہیں پہنچےگا جس كا موسیٰ علیہ السلام وعده دلا رہےتھے، لفظ بعض کا انتخاب اس لئے تھاتاكہ ان سے نرم گداز گفتگو ہو، موسیٰ علیہ السلام كیلئے كسى بھى تعصب سےگریز ہو، فرعون اور اسكى قوم سے خیرخواہى كا اظہار ہو، توامید ہے كہ وه لوگ حق قبول كرلیں۔ (ابن جزى: ۲؍۲۸۰)\nآل فرعون كے اس مومن بندے نے (بعض الذي يعدكم) كیوں كہا؟ حالانكہ انہیں وه سارا عذاب پہونچے گا جس كا ان سے وعده ہے.\nوَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ ٣٠\n(وقال الذي آمن) اس مومن بندے نے اپنى قوم كو دوباره دین کی دعوت دی ، ان كى ہدایت سے مایوس نہیں ہوا، جیسا كہ الله كى طرف دعوت دینے والے ناامید نہیں ہوتےہیں، برابر لوگوں كو رب كى طرف بلاتے رہتےہیں، کوئی انہیں اس كا م سے روك نہیں سكتا، جسے دعوت دیتے ہیں اسكى سركشى بھی انہیں تکرار دعوت سے باز نہیں ركھ پاتى ہے۔ (السعدى : ۷۳۷)\nآیت میں ، اصحاب دعوت كیلئے مایوس نہ ہونے كےسلسلے میں ایك عظیم ہدایت ہے، اسے بیان كیجئے.\nوَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ ٣٢\nقیامت كےدن ہر شخص كو اس كےامام كے ذریعے پكارا جائےگا، وه خود بھى ایك دوسرے كو آواز دیں گے، جنت والے جہنم والوں كو ، جہنم والے جنت والوں كو پكاریں گے۔ اعراف والوں كو بلایا جائےگا، خوش بخت وبدبخت كو نداء دى جائےگى كہ فلاں ابن فلاں سعادت مند ہے اب اسے كبھى بدبختى كا سامنا نہ ہوگا اور فلان ابن فلاں بدبختى كا شكار ہوگیا اب وه كبھى خوش بخت نہیں ہوسكتا۔ اور جب موت كو ذبح كردیا جائےگا تو پكار كر كہا جائےگا: اے اہل جنت ! اب ہمیشہ رہنا ہے ، كبھى موت نہیں آئےگى، اور اے اہل دوزخ! تمہیں بھى ہمیشہ ہمیش عذاب چکھنا ہے ، اب كبھى موت بھی نہیں آئےگى۔ (البغوى: ۴؍۴۲)\nقیامت كےدن كو (يوم التناد ) كیوں كہا گیا ہے؟\nwords\nعُذتُميں نے پناه مانگي.\nظَاهِرِينَغالب/ اونچے.\nيَومَ التَّنَادِقيامت كا دن / جب لوگ ايك دوسرے كو بلائيں گے.\nمُدبِرِينَبھاگتے هوئے.\nعَاصِمٍبچانے والا؛ جو تم سے روكے."],[471,"§غافر\ndeeds\nالله كى ناراضگى اور بغیر علم كے بحث وتكرار كرنے سے الله كى پناه طلب كیجئے.\nكسى غافل انسان كو حكمت كے ساتھ بہترین اسلوب میں ، سابقہ امتوں كے نیك لوگوں كى اقتداء كرتےہوئے الله كى طرف بلائیے .\nآج كوئى ایسا كام انجام دیجئے جسے آپ نے ابھى تك نہیں كیا ہےاور الله سے یہ امید ركھئے كہ اسكے بدلے آپ كو جنت نصیب فرمائےگا.\nguid\nعلم كے بغیر بحث وتكرار سے بچئے.\nیہ تباہى كا پیش خیمہ ہے كہ آپ كے برے كام بھى مزین كردئیے جائیں پھر آپ كى نگاہوں میں وه بھلے لگنے لگیں، اس سے الله كى پناه.\nاس بات پر پختہ یقین ركھئے كہ اللہ ضرور مدد فرمائےگا، اپنے اولیا ء كو زمین كا وارث بنائے گا اور اعدائے اسلام كو ذلیل ورسوا كرےگا.\nrefl\nوَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ ٣٤\nمرد مومن نےجب دیكھا نصیحت و خیر خواہى کا فائدہ نہیں ہے ، اور وہ لوگ موسیٰ علیہ السلام كو جھٹلانے پر اترے ہوئے ہیں تو نصیحت کے ایک اور اسلوب کو اپناتے ہوئے ان کے آباء و اجداد کے ماضى کے کردار کی روشنی میں ان كى ملامت كا طریقہ اختیار كیا اور انہیں یاد دلایا كہ تم اسى قوم كى ذریت ہو جس نے یوسف علیہ السلام كو جھٹلادیا تھا جب وه واضح نشانیاں لے كر آئےتھے، گویا حق كى طرف بلانے والوں كو جھٹلانا تمہارے اسلاف كا شیوه رہاہے اور یہ صفت وہیں سے تمہارے اندر آئی ہے۔ (ابن عاشور: ۲۴؍۱۳۸)\nآیت كریمہ كا ماقبل سے كیا تعلق ہے؟\nكَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ\nٹھیك اسى طرح اپنے رب كى موافقت میں الله كے مومن بندے بھى اس رویے سے شدید نفرت كرتےہیں، یہ الله تعالىٰ كے خاص بندےہیں، چنانچہ ان كا ایسے لوگوں کو ناپسند كرنا اس بات كى دلیل ہے کہ ایسے لوگ بہت قبیح اور برے ہیں۔(السعدى: ۷۳۸)\nعلماء اور الله كےنیك بندےاگر كسى سے سخت نفرت كرتےہیں تو سمجھئے كہ اسكى حالت انتہائى نازك ہے اور اس پر تدارك واصلاح كى كوشش بہت ضرورى ہے، اسے آیت كى روشنى میں واضح كیجئے.\nأَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ\nجب فرعون نے اپنے لشكر وخواص كے روبرو كہا: (فأطَّلِع إلى إله موسى) تو اس كے اس كلام سے موسیٰ علیہ السلام كے معبود كا اقرار لازم آرہا تھا اسى لئے اس نےتدارک کرتے ہوئےگھبراہٹ میں فورا كہا: (وإني لأظنه كاذبًا). (ابن عطیہ: ۴؍۵۶۰)\nآیت كى شروعات اور فرعون كے اس قول: (وإني لأظنه كاذبًا) میں كیا مناسبت ہے؟\nأَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ٣٧\n(وإني لأظنه كاذبًا) یہ جملہ معترضہ ہے، اسے ہامان اور اسكى قوم كا یہ گمان دور كرنے كیلئے لایاگیا ہےكہ موسیٰ علیہ السلام کی دعوت نے فرعون کے اپنے معبود و دین پر یقین کو متزلزل کردیا ہے، اور اب وہ معرفت حق کی دلیلوں کی تلاش و جستجو کا ارادہ کرلیا ہے، لیکن فرعون نے اپنے اس قول و عمل سے یہ باور کرانا چاہا كہ وہ اب بھى موسیٰ علیہ السلام کے رب کی نفی حسی دلیلوں سے کرناچاہتا ہے۔ (ابن عاشور: ۲۴؍۱۴۷)\n(وإني لأظنه كاذبًا)اس جملہ كے ذریعے فرعون كیا فائده ثابت کرنا چاہتا تھا؟\nوَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ٣٧\nفرعون کے بلند عمارت تعمیر کرنے کے حکم کو(كَيْدُ) (چال ، سازش) كہاگیا ہے كیونكہ یہ ایسا عمل ہے جس كا ظاہری مفہوم مراد نہیں ہے، بلكہ وه اپنى قوم والوں كو موسیٰ علیہ السلام كے جھوٹے ہونے کے وہم میں مبتلا رکھنا چاہتا تھا۔ (ابن عاشور: ۲۴؍۱۴۸)\nفرعون كے بالاخانہ تیار كرنے كے حكم كو (كَيْدُ) سازش كیوں كہاگیا ؟\nوَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ٣٧\nفرعون كى وه حیلہ سازى جسے اس نے موسیٰ علیہ السلام كے معبود كو جھانكنے كیلئے اپنایا تھا، اس میں گھاٹا ، مال كى بربادى اور دھوكہ تھا ، كیونكہ بلند عمارت بنانے میں جو مال صرف كیا وه ضائع ہوا جس مقصد كیلئے مال اڑایا وه حاصل نہ ہوا لہذا اس میں خساره اور نرى تباہى وبربادى تھى۔(الطبرى : ۲۱؍۳۸۸)\nبتائیے (تَبَاب) كیا ہے اور فرعون كى حیلہ سازى كو (تَبَاب)سے متصف كیوں كیا گیاہے، ؟\nيَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ ٣٩\nحیات دنیوى سے تھوڑا سا فائده اٹهایا جاتاہے پھر یہ ختم ہوجائےگى۔ (وإن الآخرة هي دار القرار) (اور ہمیشگى كا گھر تو آخرت ہے) (الْقَرَارِ)یعنى دوام واستقرار، (الدار الآخرة)سے مراد جنت اور جہنم ہیں كیونكہ یہ فنا نہیں ہوں گے۔ (القرطبى: ۱۸؍۳۶۱)\nاس مومن بندے نے دنیا اور آخرت كى حقیقت بیان كرکے اپنی قوم والوں کو الله كى دعوت كیسے دى؟\nwords\nشَكٍّشك و شبه.\nمُرتَابٌالله تعاليٰ ميں شك كرنے والا.\nيَطبَعُوه مهر لگاتا هے.\nصَرحًابهت بڑي عمارت.\nتَبَابٍخساره والي؛ تباه هونے والي."],[472,"§غافر\ndeeds\nكسى گنہگار كو توبہ كى طرف ، یا كسى كافر كو اسلام كى طرف دعوت دیں، اور اپنى شفقت اورحرص كا اس پر اظہار كریں.\nکوئی ایسا كام یاد كریں جس نے آپ كو غمگین وپریشان كردیا ہو ، پھر اس بارے میں صرف الله پر بھروسہ كریں اس لئے كہ وہى آپ كیلئےكافى ہے.\nقبرستان كى زیارت كریں، پھر عذاب قبر سے الله كى پناه مانگیں.\nguid\nدعوت الى الله كےمیدان میں موثر ناصحانہ اسلوب استعمال كریں.\nدیکھئے ! آل فرعون كے مومن نے كیا ہى بہتر طریقے سے اپنى قوم كےسامنے اپنى وعظ ونصیحت ختم كی ہے.\nسخت گھاٹے كا شكار كم عقل ہى ہوتےہیں كہ دنیا میں جن سرداروں كے پیچھے پیچھے چلتےتھے، آخرت میں وہى ان سے دامن جھاڑ لیں گے.\nrefl\nوَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ٤٤ فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ\nیہ آیت اس بات کی دلیل ہے كہ جس نے اپنا معاملہ الله كے حوالے كردیا الله اس کا ساتھ دیتا ہے۔ (ابن جزى: ۲؍۲۸۲)\nمذكوره دونوں آیتوں سے ایك مسلمان كیا فائده اٹھا سكتاہے یا اسے کونسا سبق ملتا ہے؟\nفَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ\nیعنى اللہ نے اسے عذاب كى مختلف شكلوں میں مبتلا ہونے سے بچا لیا ، جب لوگوں نے اسے(اذیت و تکلیف دینے کی غرض سے) طلب كیا تو وہاں نہیں پایا، كیونكہ اس نے اپنا معاملہ الله كو سونپ ركھا تھا۔ (القرطبى : ۱۸؍۳۶۳)\nآل فرعون كے مومن كا كیا انجام ہوا جس نے اپنا معاملہ الله كو سونپ ركھا تھا؟\nوَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ ٤٥\nڈوب كر مرنا یہ برا عذاب ہے؛ كیونكہ ڈوبنے والا سانس كے بند ہوجانے سے ایك وقفے تك عذاب میں مبتلا رہتا ہے، اسطرح كہ كبھى پانى كےاوپر آتاہے، اور كبھى اندر ڈوبتاہے، اور ساتھ ہی موجوں كى ہولناكى اسے خوف میں ركھتى ہے جس سے اسے ہلاكت كا یقین رہتاہے، پھر اسے یہ خطره بھى لاحق رہتاہے كہ زنده اور مرده ہر صورت میں اسے مچھلیاں كھاجائیں گى، اس طرح یہ زندگى میں بھى ایك دردناك عذاب ہے اور مرنے كے بعد بھى ذلت ورسوائى ہے كہ لوگوں كے درمیان اسے اسى عذاب كے حوالے سے یاد كیا جائیگا۔ (ابن عاشور: ۲۴؍۱۹۸)\nڈوب جانے كو برا عذاب كیوں كہاگیا ہے؟\nٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ ٤٦\nدر اصل ان كى روحیں صبح وشام جہنم پر پیش كى جاتى ہیں ، اور ایسا قیامت تك ان كےساتھ ہوتا رہےگا ، پھر قیامت كےدن ان كى روحوں اور جسموں دونوں كو جہنم میں اكٹھا كردیا جائےگا۔ اسى لئے الله نے فرمایا: (ويوم تقوم الساعة أدخلوا آل فرعون أشد العذاب) یعنى جس كى وجہ سے تكلیف میں مزید اضافہ اور عذاب میں مزید سختى ہوگى۔ نیز یہ آیت (النار يعرضون عليها غدوًا وعشيًا) اہل سنت والجماعت كیلئے عذابِ برزخ كے مسئلے میں بہت بڑى بنیادى دلیل ہے۔(ابن كثیر: ۴؍۸۳)\nعذاب قبر كے اثبات پر آپ اس آیت سے استدلال كیسےكریں گے.؟\nوَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ ٤٧\nبڑے سرداروں سے كمزور طبقہ كےلوگوں كے اس كلام كو حقیقت پر محمول كیا جاسكتا ہے كیونكہ ان سے ایسى بات كا امكان ہے كہ دنیا میں یہ پریشانى كے وقت انہیں كى پناه لیتےتھے، اسلئے وہاں بھى یہى سوچیں گے كہ ان كے معاملات كى ذمیدارى انہیں كےپاس ہوگى۔ اسى لئے وه سردار انہیں ایسا جواب دیں گے جس سے انہیں یہ پتہ چل جائےگا كہ آج كے دن عاجزى اور كچھ نہ كرپانے میں دونوں برابر ہیں، اور كہیں گے: (إِنَّا كُلٌّ فِيهَا) ہم سب اس میں رہیں گے، یعنى اگر ہم تمہارے لئے كچھ كرسكتے تو پہلے اپنے لئے کرتے ۔ اور یہ بھى احتمال ہے كہ كمزور طبقے كى یہ فریاد در حقیقت تخفیف عذاب كیلئے نہیں ہے بلكہ یہ ان كى طرف سے ایك ڈانٹ اور پھٹكار ہے كہ تم ہمیں شرك كى طرف دعوت دیتےتھے جس کا انجام یہ ہے کہ آج ہم عذاب میں مبتلا ہیں ، تو کیا تم ہم سے اس عذاب كو ٹال سكتےہو؟ (ابن عاشور: ۲۴؍۱۶۱)\nآیت كریمہ كےاندر سرداروں سے كمزور طبقہ كےلوگوں كى جو گفتگوبیان ہوئى ہے اس کا كیا فائده ہے؟\nقَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ ٤٨\nاس آیت میں قوموں كے سربراہوں اور رہنماؤں كیلئے عبرت اورنصیحت ہے اگر وه انجام جانتے ہوئے بھی اپنی جانوں اور قوموں كےساتھ اپنے اقوال و افعال کے ذریعے دھوكہ دیتے ہیں اور انہیں خطرات سے دوچار كرتےہیں تو وه یقیناً دنیا میں ذلت ورسوائى اور آخرت میں دوگنا عذاب كے مستحق ہیں جیسا كہ الله نے فرمایا ہے: ﴿وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡ﴾ یعنى وه اپنا بوجھ تو اٹھائیں گے ہى ساتھ ہى دوسروں كا بوجھ بھى اٹھائیں گے۔ [العنکبوت:۱۳]، اور اگر وہ سیادت و زعامت کے پرپیچ راہوں میں اپنی کمی و کوتاہی کے انجام سے بے خبر ہوکر کود پڑے ہیں تو وہ قوموں كى امامت كى قابل ِ اعتماد اہلیت و صلاحیت نہ رکھنے کی وجہ سے ملامت کے مستحق ہیں کیونکہ انہوں نے عوام کو گمراہ کیا ہے بھٹکایا ہے اور ان کے ساتھ کھائی میں جاگرے ہیں۔ (ابن عاشور : ۲۴؍۱۶۳)\nآیت كریمہ سے قوموں كے سربراہوں اور رہنماؤں كیلئے عبرت و نصیحت کے پہلو واضح کیجئے.\nوَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ ٤٩\nضمیر جمع مذكر حاضر كى طرف (رَبّ) کی اضافت میں ایک طرح سے دعا پر ابھارنا ہے، یعنى تم لوگ قبولیت دعا كے زیاده مستحق ہو۔ پھر جب انہوں نے قبولیت دعا كا یقین كرلیا تو تخفیف عذاب كیلئے انہیں سے درخواست كى کہ کچھ مدت یا ایك ہى دن کی تخفیف کردی جائے۔ اور اپنے سرداروں کے مقابلے میں ان سے جہنم كے عذاب كى تخفیف کا سوال، انہیں زیادہ مفید معلوم ہوا۔ (ابن عاشور: ۲۴؍۱۶۴)\nجمع مذكر حاضر كى ضمیر کی طرف(رَبّ)کی اضافت کا كیا فائده ہے؟\nwords\nلاَ جَرَمَكوئي حرج نهيں۔ حق بات.\nلَيسَ لَهُ دَعوَةٌجس كي عبادت كا كوئي استحقاق نهيں.\nوَأُفَوِّضُميں توكل كرتا هوں/ پناه مانگتا هوں.\nوَحَاقَنازل هوا؛ گھير ليا.\nيَتَحَآجُّونَوه جھگڑا كرتے هيں.\nمُغنُونَبچانے والے؛ نجات دلانے والے."]])